window.POEM_DB=window.POEM_DB||{};POEM_DB["song_046"]={"n":"戴复古","dyn":"宋","poems":[{"t":"和郑润甫提举见寄 其二","f":"五言律诗","c":["长身如病鹤，吟苦如蟋蟀。","顾此憔悴姿，痴生年八秩。","举世皆好竽，老夫方鼓瑟。","梅花莫笑人，茅檐炙朝日。"]},{"t":"醉吟","f":"七言律诗","c":["草茅无路谒君王，白首终为田舍郎。","近读南华资旷达，欲师西洛愧荒唐。","乾坤万象供诗料，风月一楼为醉乡。","日晚栖禽归自乐，飞鸣不是怨斜阳。"]},{"t":"次王应求韵","f":"七言律诗","c":["逐日轮蹄走四方，来来去去为何忙。","无人肯问山林乐，举世争趋名利场。","以道自脩身是宝，无求何用智为囊。","爱梅栽竹平生语，吐出清风六月凉。"]},{"t":"寄刘潜夫","f":"七言绝句","c":["八斗文章用有馀，数车声誉满江湖。","今年好献南郊赋，幕府文章有暇无。"]},{"t":"题赵忠定公雪锦楼诗","f":"七言律诗","c":["九鼎重安国势牢，功名易办谤难逃。","手扶日月扫云雾，身向江湖直羽毛。","雪锦诗成先谶兆，金縢书启见勤劳。","纷纷论定知忠定，不负朝廷两字褒。"]},{"t":"九日","f":"七言绝句","c":["醉来风帽半欹斜，几度他乡对菊花。","最苦酒徒星散后，见人儿女倍思家。"]},{"t":"入闽道中","f":"七言绝句","c":["山中寂寞去程赊，莫惜频频到酒家。","行李萧然还不倍，担头颠倒插梅花。"]},{"t":"山中见梅","f":"七言绝句","c":["踏破溪边一径苔，好山好竹少人来。","有梅花处惜无酒，三嗅清香当一杯。"]},{"t":"山村 其二","f":"七言绝句","c":["万竹稍头云气生，四风吹雨又吹晴。","题诗未了下山去，一路吟声杂水声。"]},{"t":"山村 其一","f":"七言绝句","c":["山崦谁家绿树中，短墙半露石榴红。","萧然门巷无人到，三两孙随白发翁。"]},{"t":"山村","f":"七言绝句","c":["雨过山村六月凉，田田流水稻花香。","松边一石平如榻，坐听风蝉送夕阳。"]},{"t":"巾子山翠微阁","f":"七言绝句","c":["双峰直上与天参，僧共白云栖一庵。","今古诗人吟不尽，好山无数在江南。"]},{"t":"中秋李漕冰壶燕集","f":"七言绝句","c":["把酒冰壶接胜游，今年喜不负中秋。","故人心似中秋月，肯为狂夫照白头。"]},{"t":"书事","f":"七言绝句","c":["打鼓行船未有期，恰如江上阻风时。","诗中一段闲公事，幸不妨人吃荔枝。"]},{"t":"无题","f":"七言绝句","c":["忆闻春燕语雕梁，又听秋鸿叫断肠。","一缕沉烟飞不过，两楼相对立斜阳。"]},{"t":"见山居可喜","f":"七言绝句","c":["一溪盘曲到阶除，四面青山画不如。","脩竹罩门梅夹路，诗人居处野人居。"]},{"t":"东池","f":"七言绝句","c":["来寻吾祖隐居处，袅袅春风吹酒旗。","手把梅花寄愁绝，东池只是旧东池。"]},{"t":"冬至","f":"七言绝句","c":["时光流转寻常事，世故惊心感慨多。","一岁休祥在云气，今朝云气果如何。"]},{"t":"宁乡道上遇张伯声","f":"七言绝句","c":["山禽调舌待春哢，江雨收声开晓晴。","偶遇故人同杖履，梅花树下一诗成。"]},{"t":"汀州道上","f":"五言绝句","c":["宇内何牢落，客行双鬓华。","千山万山底，老眼付梅花。"]},{"t":"买归舟篙子请占牌戏成口号","f":"七言绝句","c":["诈称官职不如休，白板无题又可羞。","只写江湖散人号，不然书作醉乡侯。"]},{"t":"刘子及赠瑞桂","f":"七言绝句","c":["秋光点点明人眼，不比寻常岩桂花。","天与刘郎作嘉瑞，枝枝金粟间丹砂。"]},{"t":"同蕲州上官节推登光州增胜楼","f":"七言绝句","c":["增胜楼中共倚栏，平原渺渺接青山。","夕阳明处人烟少，胡马曾来闯五关。"]},{"t":"戏题诗藁","f":"七言绝句","c":["冷澹篇章遇赏难，杜陵清瘦孟郊寒。","黄金作纸珠排字，未必时人不喜看。"]},{"t":"扬州端午呈赵帅","f":"七言绝句","c":["榴花角黍斗时新，今日谁家不酒樽。","堪笑江湖阻风客，却随蒿艾上朱门。"]},{"t":"次韵卢申之正字野兴","f":"七言绝句","c":["芋圃蔬畦接井湄，茅檐四面槿篱围。","门前尽日无人过，牛渡横塘野鸭飞。"]},{"t":"次韵李伯高","f":"七言绝句","c":["莲幕高吟冰雪篇，天才秀发思华年。","千金买得惊人句，落在鸡林渡海船。"]},{"t":"次韵谷口郑东子见寄 其四","f":"七言绝句","c":["一生飘泊客途中，扶技从人类百工。","白首归来入诗社，犹思渭北与江东。"]},{"t":"次韵谷口郑东子见寄 其五","f":"七言绝句","c":["吾乡自昔诗人少，委羽先生后有翁。","坐客无毡君莫笑，云台有集继家风。"]},{"t":"次韵谷口郑东子见寄 其三","f":"七言绝句","c":["相看俱作白头翁，出处规模自不同。","我走江湖作狂梦，君能面壁课成功。"]},{"t":"次韵谷口郑东子见寄 其二","f":"七言绝句","c":["不管家居四壁空，琢成佳句有神工。","谪仙会有金銮召，莫道诗人命不通。"]},{"t":"次韵谷口郑东子见寄 其六","f":"七言绝句","c":["自笑诗人多好酒，君能不饮任樽空。","劝君莫倚醒醒眼，却笑傍人醉面红。"]},{"t":"次韵谷口郑东子见寄 其一","f":"七言绝句","c":["闭门觅句饭牛翁，囊有新诗不怕穷。","十里梅花生眼底，九峰山色满胸中。"]},{"t":"次韵郭子秀晓行","f":"七言绝句","c":["脱叶园林带晓鸦，马蹄步步踏霜华。","山边水际频凝顾，怕有寒梅昨夜花。"]},{"t":"江阴浮远堂","f":"七言绝句","c":["横冈下瞰大江流，浮远堂前万里愁。","最苦无山遮望眼，淮南极目尽神州。"]},{"t":"江村晚眺二首 其二","f":"七言绝句","c":["江头落日照平沙，潮退渔舠阁岸斜。","白鸟一双临水立，见人惊起入芦花。"]},{"t":"江村晚眺二首 其一","f":"七言绝句","c":["数点归鸦过别村，隔滩渔笛远相闻。","菰蒲断岸潮痕湿，日落空江生白云。"]},{"t":"观捕黄雀","f":"七言绝句","c":["披绵争啄晚禾秋，决起森然网扼喉。","一饱等闲输性命，知机万不及沙鸥。"]},{"t":"访友人家即事","f":"七言绝句","c":["烂茅遮屋竹为床，口诵时文鬓已霜。","妻病无钱供药物，自寻野草试单方。"]},{"t":"访旧","f":"七言绝句","c":["欲寻西舍问东邻，两巷都非旧住人。","唯有桑边石池在，依然春水碧粼粼。"]},{"t":"严仪卿约李友山高与权酌别","f":"七言绝句","c":["江天惨澹日凄凉，木未经霜叶未黄。","今日楼头一杯酒，明朝行客在谁乡。"]},{"t":"初夏","f":"七言绝句","c":["等闲过了一年春，雨后风光夏景新。","试把樱桃荐杯酒，欲将芍药赠何人。"]},{"t":"初夏","f":"七言绝句","c":["红紫光阴不久长，一声啼鴂静年芳。","阴阴绿树黄鹂语，将与人间作夏凉。"]},{"t":"别许季如","f":"七言绝句","c":["久不相逢喜合簪，相从未久又分襟。","扁舟自逐便风去，却恨无情江水深。"]},{"t":"庐山马上","f":"七言绝句","c":["青松路径白云关，有客来寻半日閒。","十载灞桥驴子上，争如骑马看庐山。"]},{"t":"怀家三首 其三","f":"五言绝句","c":["三年寄百书，几书到我屋。","昨夜梦中归，及见老妻哭。"]},{"t":"怀家三首 其二","f":"五言绝句","c":["强言不思家，对人作意气。","惟有布被头，见我思家泪。"]},{"t":"怀家三首 其一","f":"五言绝句","c":["白发出门来，三见梅花谢。","客路有岁年，归心无昼夜。"]},{"t":"李友山索诗卷汀州急递到昭武","f":"七言绝句","c":["清时无事更年丰，两地风光诗咏中。","可是山前无警报，旗铃千里递诗筒。"]},{"t":"李敷文酌别席上口占","f":"七言绝句","c":["客子明朝早问程，樽前今夜苦为情。","使君亦恐伤离别，不使佳人唱渭城。"]},{"t":"村景","f":"七言绝句","c":["箫鼓迎神赛社筵，藤枝摇曳打鞦韆。","坐中翁妪鬓如雪，也把山花插满颠。"]},{"t":"到南昌呈宋愿父伯仲黄子鲁诸丈 其一","f":"七言绝句","c":["一秋无便寄平安，新雁声声报早寒。","昨夜检衣开故箧，去年家信把来看。"]},{"t":"到南昌呈宋愿父伯仲黄子鲁诸丈 其二","f":"七言绝句","c":["扁舟几度到南昌，东望家山道路长。","醉里不知身是客，故人多处亦吾乡。"]},{"t":"周子益年八十赴殿 其一","f":"七言绝句","c":["七尺渔竿八十翁，钓丝轻袅荻花风。","功名未遂英雄老，人道磻溪即个中。"]},{"t":"周子益年八十赴殿 其二","f":"七言绝句","c":["抛却渔村老钓竿，手遮西日上长安。","青衫著了寻归路，莫过羊裘七里滩。"]},{"t":"定王台","f":"七言绝句","c":["长沙米换长安土，筑此崔嵬寄远观。","客子登台千载后，倚栏亦欲望长安。"]},{"t":"宝觉僧房","f":"七言绝句","c":["溪近泉声在枕边，月移梅影到窗前。","水沈烟冷灯花落，半夜酒醒人不眠。"]},{"t":"岳市胜业寺悦亭","f":"七言绝句","c":["寻幽揽胜老犹勤，但觉吟身瘦几分。","净洗一生尘上眼，细看七十二风云。"]},{"t":"招山乃诗人刘叔拟故居朱清之得其地清之赴南宫中道而返就招山卜筑不久亦去世 其一","f":"七言绝句","c":["半路袖回攀桂手，一生才遂买山心。","要知此老风流处，来向刘郎吟处吟。"]},{"t":"招山乃诗人刘叔拟故居朱清之得其地清之赴南宫中道而返就招山卜筑不久亦去世 其二","f":"七言绝句","c":["有钱可买沧浪景，无术能还梦幻身。","一段江山寄愁绝，百年不见两诗人。"]},{"t":"林下得月以木阴蔽遮为恨","f":"七言绝句","c":["夏日思栽千树林，月明恨不扫寒阴。","眼前物物皆如此，世事何能两遂心。"]},{"t":"林伯仁话别二绝 其二","f":"七言绝句","c":["茉莉花边把酒卮，桄榔树下共谈诗。","醉来一枕西窗下，酒醒方知有别离。"]},{"t":"林伯仁话别二绝 其一","f":"七言绝句","c":["别酒三杯醉不知，梅花岭外故人稀。","片心暗逐白云去，日日向君行处飞。"]},{"t":"画山","f":"七言绝句","c":["几簇云烟几段山，画成烟雨渺茫间。","扁舟三两溪桥上，一路更无人往还。"]},{"t":"盱眙北望","f":"七言绝句","c":["北望茫茫渺渺间，鸟飞不尽又飞还。","难禁满目中原泪，莫上都梁第一山。"]},{"t":"觅芍药代简岂潜","f":"七言绝句","c":["照映亭池芍药春，红红白白斗精神。","与其雨打风吹去，争似慇勤折赠人。"]},{"t":"郑子寿野趣烧烛醉梅花","f":"七言绝句","c":["古瓶斜插数枝春，此即君家劝酒人。","移取堂前双蜡烛，花边照出玉精神。"]},{"t":"钓台","f":"七言绝句","c":["万事无心一钓竿，三公不换此江山。","平山误识刘文叔，惹起虚名满世间。"]},{"t":"客中秋晚","f":"七言绝句","c":["榴花才放客辞家，客里因循见菊花。","独坐西楼对风雨，天寒犹自著轻纱。"]},{"t":"既别诸故旧独黄希声往曲江禀议未回不及语离 其一","f":"七言绝句","c":["别尽诸君不见君，客愁多似海南云。","一声何处离群雁，那向江村静处闻。"]},{"t":"既别诸故旧独黄希声往曲江禀议未回不及语离 其二","f":"七言绝句","c":["老年怀抱晚秋天，欲去思君重黯然。","闻道归来有消息，江头错认几人船。"]},{"t":"昭武太守王子文日与李贾严羽共观前辈一两家诗及晚唐诗因有论诗十绝子文见之谓无甚高论亦可作诗家小学须知 其八","f":"七言绝句","c":["诗本无形在窈冥，网罗天地运吟情。","有时忽得惊人句，费尽心机做不成。"]},{"t":"昭武太守王子文日与李贾严羽共观前辈一两家诗及晚唐诗因有论诗十绝子文见之谓无甚高论亦可作诗家小学须知 其六","f":"七言绝句","c":["飘零忧国杜陵老，感寓伤时陈子昂。","近日不闻秋鹤唳，乱蝉无数噪斜阳。"]},{"t":"昭武太守王子文日与李贾严羽共观前辈一两家诗及晚唐诗因有论诗十绝子文见之谓无甚高论亦可作诗家小学须知 其四","f":"七言绝句","c":["意匠如神变化生，笔端有力任从横。","须教自我胸中出，切忌随人脚后行。"]},{"t":"昭武太守王子文日与李贾严羽共观前辈一两家诗及晚唐诗因有论诗十绝子文见之谓无甚高论亦可作诗家小学须知 其三","f":"七言绝句","c":["曾向吟边问古人，诗家气象贵雄浑。","雕锼太过伤于巧，朴拙惟宜怕近村。"]},{"t":"昭武太守王子文日与李贾严羽共观前辈一两家诗及晚唐诗因有论诗十绝子文见之谓无甚高论亦可作诗家小学须知 其二","f":"七言绝句","c":["古今胸次浩江河，才比诸公十倍过。","时把文章供戏谑，不知此体误人多。"]},{"t":"昭武太守王子文日与李贾严羽共观前辈一两家诗及晚唐诗因有论诗十绝子文见之谓无甚高论亦可作诗家小学须知 其五","f":"七言绝句","c":["陶写性情为我事，留连光景等儿嬉。","锦囊言语虽奇绝，不是人间有用诗。"]},{"t":"昭武太守王子文日与李贾严羽共观前辈一两家诗及晚唐诗因有论诗十绝子文见之谓无甚高论亦可作诗家小学须知 其十","f":"七言绝句","c":["草就篇章只等闲，作诗容易改诗难。","玉经雕琢方成器，句要丰腴字要安。"]},{"t":"昭武太守王子文日与李贾严羽共观前辈一两家诗及晚唐诗因有论诗十绝子文见之谓无甚高论亦可作诗家小学须知 其一","f":"七言绝句","c":["文章随世作低昂，变尽风骚到晚唐。","举世吟哦推李杜，时人不识有陈黄。"]},{"t":"昭武太守王子文日与李贾严羽共观前辈一两家诗及晚唐诗因有论诗十绝子文见之谓无甚高论亦可作诗家小学须知 其七","f":"七言绝句","c":["欲参诗律似参禅，妙趣不由文字传。","个里稍关心有误，发为言句自超然。"]},{"t":"泉广载铜钱入外国","f":"七言绝句","c":["人望南风贾舶归，利通中国海南夷。","珠珍犀象来无限，但恐青钱有尽时。"]},{"t":"赵苇江与东嘉诗社诸君游一日携吟卷见过一语谢其来","f":"七言绝句","c":["白首无聊老病躯，一心唯觅死头颅。","时人误作梅花看，今日枝头雪也无。"]},{"t":"重阳","f":"七言绝句","c":["茱萸半紫菊花黄，时节催人日夜忙。","便使老夫年满百，无过二十二重阳。"]},{"t":"桂","f":"七言绝句","c":["金谷园林知几家，竞栽桃李作春华。","无人得似天工巧，明月中间种桂花。"]},{"t":"海棠","f":"七言绝句","c":["十月园林不雨霜，朝曦赫赫似秋阳。","夜来听得游人语，不见梅花见海棠。"]},{"t":"都中冬日","f":"七言绝句","c":["脱却鹴裘付酒家，忍寒图得醉京华。","一冬天气如春暖，昨日街头卖杏花。"]},{"t":"陶侃柏","f":"七言绝句","c":["四绝堂前枯柏树，晋人栽植宋人吟。","无枝无叶无吟处，聊寓一时怀古心。"]},{"t":"寄上赵南仲枢密 其二","f":"七言绝句","c":["能为明哲保身谋，富贵功名总罢休。","早向急流中勇退，归来闲伴赤松游。"]},{"t":"寄上赵南仲枢密 其一","f":"七言绝句","c":["贵为公相不如归，一夕飘然去不知。","乐在五湖风月底，扁舟载酒对西施。"]},{"t":"寄玉溪林逢吉六首 其六","f":"七言绝句","c":["王建不能怜贾岛，吟边怀抱向谁开。","扶病欲迎新太守，不知千骑几时来。"]},{"t":"寄玉溪林逢吉六首 其五","f":"七言绝句","c":["老夫时作白头吟，爨下焦桐孰赏音。","敢望荆溪作诗跋，自惭弊帚享千金。"]},{"t":"寄玉溪林逢吉六首 其四","f":"七言绝句","c":["陋巷深深屋数椽，以文为业砚为田。","一觞一饭常留客，知是君家内子贤。"]},{"t":"寄玉溪林逢吉六首 其三","f":"七言绝句","c":["心腹相知会面稀，一春未有盍簪期。","西窗风雨愁眠夜，梦到君家赋小诗。"]},{"t":"寄玉溪林逢吉六首 其二","f":"七言绝句","c":["问君那向城中住，赖有清风濯市尘。","门外数根杨柳树，细看别作一家春。"]},{"t":"寄玉溪林逢吉六首 其一","f":"七言绝句","c":["经年不见玉溪翁，百里江山万里同。","无计相从话心曲，时挥一纸寄西风。"]},{"t":"寄兴 其一","f":"五言绝句","c":["长愿如人意，一生无别离。","妾当年少日，花似半开时。"]},{"t":"寄兴 其二","f":"五言绝句","c":["黄金无足色，白璧有微瑕。","求人不求备，妾愿老君家。"]},{"t":"寄后村刘潜夫 其三","f":"七言绝句","c":["客游仙里见君时，拥絮庵中共说诗。","别后故人知我否，年几八十病支离。"]},{"t":"得早梅一枝携访酒家","f":"七言绝句","c":["旗亭沽酒少裴回，左手梅花右手杯。","眼见枝头开数蕊，春风自我掌中来。"]},{"t":"晚春","f":"七言绝句","c":["池塘渴雨蛙声少，庭院无人燕语长。","午枕不成春草梦，落花风静煮茶香。"]},{"t":"淮村兵后","f":"七言绝句","c":["小桃无主自开花，烟草茫茫带晓鸦。","几处败垣围故井，乡来一一是人家。"]},{"t":"绿阴亭自唐时有之到今五百年卢肇二三公题诗之后吟声寂寂久矣亭前古木不存绿阴之名殆成虚设今诗人李贾友山作尉于此实居此亭公事之暇与江山风景应接境因人胜见于吟笔多矣友人石屏戴复古访之相与周旋于亭上题四绝句以记曾来 其二","f":"七言绝句","c":["惨惨秋风吹客襟，唐人遗迹宋人吟。","浮云世事多迁变，不独此亭无绿阴。"]},{"t":"绿阴亭自唐时有之到今五百年卢肇二三公题诗之后吟声寂寂久矣亭前古木不存绿阴之名殆成虚设今诗人李贾友山作尉于此实居此亭公事之暇与江山风景应接境因人胜见于吟笔多矣友人石屏戴复古访之相与周旋于亭上题四绝句以记曾来 其四","f":"七言绝句","c":["政是国家多事秋，渝川县尉亦风流。","吟诗不废公家事，坐使孟郊输一筹。"]},{"t":"绿阴亭自唐时有之到今五百年卢肇二三公题诗之后吟声寂寂久矣亭前古木不存绿阴之名殆成虚设今诗人李贾友山作尉于此实居此亭公事之暇与江山风景应接境因人胜见于吟笔多矣友人石屏戴复古访之相与周旋于亭上题四绝句以记曾来 其一","f":"七言绝句","c":["五百年前作此亭，亭前古木绿阴清。","而今古木无存者，赖有新亭系旧名。"]},{"t":"绿阴亭自唐时有之到今五百年卢肇二三公题诗之后吟声寂寂久矣亭前古木不存绿阴之名殆成虚设今诗人李贾友山作尉于此实居此亭公事之暇与江山风景应接境因人胜见于吟笔多矣友人石屏戴复古访之相与周旋于亭上题四绝句以记曾来 其三","f":"七言绝句","c":["远山横碧一溪清，白鸟飞边落照明。","吏散庭阶一无事，绿阴亭上又诗成。"]},{"t":"船过桐江怀郭圣与","f":"七言绝句","c":["只言君在桐江住，及到桐江不见君。","日暮空山独惆怅，不知又隔几重云。"]},{"t":"鄂渚解缆","f":"七言绝句","c":["日日言归不得归，今朝真个是归期。","西楼烟水南楼月，别后何人更有诗。"]},{"t":"雪中观梅郑子寿畏寒不到","f":"七言绝句","c":["孤负溪桥雪与梅，怕寒不肯出门来。","欲邀郑老同清赏，争得梅花六月开。"]},{"t":"湖上","f":"七言绝句","c":["湖上团团三十里，若非杨柳即楼台。","城门未锁黄昏月，更住旗亭把一杯。"]},{"t":"湖南漕李革夫被召乃丐归 其一","f":"七言绝句","c":["浪说归朝归豫章，新居万柳百花傍。","何如表奏明光殿，乞取东湖作醉乡。"]},{"t":"湖南漕李革夫被召乃丐归 其二","f":"七言绝句","c":["轩冕难遮两鬓华，官居虽好不如家。","一心懒上朝天马，要趁春风归种花。"]},{"t":"湘中遇翁灵舒","f":"七言绝句","c":["天台山与雁山邻，只隔中间一片云。","一片云边不相识，三千里外却逢君。"]},{"t":"湘西寺观澜轩","f":"七言绝句","c":["东岸楼台西岸山，潇湘一片在中间。","红尘不到沧波上，僧与白云相对闲。"]},{"t":"登楼绝句和者甚多又从而用韵择其可录者录之 其一","f":"七言绝句","c":["劳生百计不如闲，合把人间比梦间。","天与老夫供享用，一楼风月两屏山。"]},{"t":"登楼绝句和者甚多又从而用韵择其可录者录之 其三","f":"七言绝句","c":["小楼题了又还题，一段风流在水西。","白鸟飞来知乡背，青山元自有高低。"]},{"t":"登楼绝句和者甚多又从而用韵择其可录者录之 其四","f":"七言绝句","c":["富贵于人造物悭，出门又觉世途艰。","楼头适意三杯酒，禾末清风雨后山。"]},{"t":"登楼绝句和者甚多又从而用韵择其可录者录之 其二","f":"七言绝句","c":["心地清凉日日秋，怕沾尘土莫低头。","置身不在众人下，处处皆成百尺楼。"]},{"t":"越上青店候别杨休文","f":"七言绝句","c":["千载江湖共此心，老来相见怕分襟。","手搔白发望君至，车马不来溪水深。"]},{"t":"道乡台","f":"七言绝句","c":["万里南迁直谏臣，世间无地可容身。","夜冲风雨过湘水，赖有青山作主人。"]},{"t":"新岁","f":"七言绝句","c":["新年试笔欲题诗，老去才衰得句迟。","春事未容桃李觉，梅花开到北边枝。"]},{"t":"楼上观山","f":"七言绝句","c":["九陌黄尘没马头，人来人去几时休。","谁家有酒身无事，长对青山不下楼。"]},{"t":"溪上","f":"七言绝句","c":["小楼萧洒面晴川，袅袅西风扫暮烟。","碧水明霞两相照，秋光全在夕阳天。"]},{"t":"溪上","f":"七言绝句","c":["山腰有路穿脩竹，水面无桥涉浅沙。","夹岸人家尽农圃，秋风吹老木棉花。"]},{"t":"端午丰宅之提举送酒","f":"七言绝句","c":["海榴花上雨萧萧，自切菖蒲泛浊醪。","今日独醒无用处，为公痛饮读离骚。"]},{"t":"酴醾","f":"七言绝句","c":["东风满架索春饶，三月梁园雪未消。","剩馥何人炷兰麝，柔枝无力带琼瑶。"]},{"t":"蕲口阻风务官点税","f":"五言绝句","c":["江涨行无路，西风又打头。","颇闻商妇怨，自作贾胡愁。"]},{"t":"豫章东湖","f":"五言绝句","c":["亭亭绿荷叶，密密罩清波。","为见湖光少，却嫌荷叶多。"]},{"t":"题尹惟晓芙蓉翠羽图","f":"七言绝句","c":["何人妙笔起秋风，吹破枝头烂漫红。","翠羽飞来又飞去，一心祇在蓼花丛。"]},{"t":"题牛图","f":"七言绝句","c":["牡丹花下连宵醉，今日闲看黑牡丹。","得此躬耕东海曲，一贫无虑百忧宽。"]},{"t":"题吴熙仲云萍录","f":"七言绝句","c":["家在蓬莱海上居，出身履历一时无。","姓名羞上云萍录，本是烟波一钓徒。"]},{"t":"题陈景明梅庐 其一","f":"七言绝句","c":["手栽梅核待成林，慈母当年属望深。","梅未成林人已往，空酸孝子一生心。"]},{"t":"题陈景明梅庐 其二","f":"七言绝句","c":["思亲如海渺无涯，观物惊心感岁华。","谁见诗人心苦处，年年挥泪看梅花。"]},{"t":"题郑子寿野趣","f":"七言绝句","c":["菜花园圃槿花篱，麦满前坡水满池。","野老横竿拦鸭过，牧儿携笛倚牛吹。"]},{"t":"题梅岭云封四绝 其四","f":"七言绝句","c":["南迁过岭面无惭，前有东坡后澹庵。","儿辈欲知当日事，青山解语水能谈。"]},{"t":"题梅岭云封四绝 其三","f":"七言绝句","c":["凿破青山两壁开，石头路上踏成埃。","梅花自与白云笑，几见夷齐出岭来。"]},{"t":"题梅岭云封四绝 其一","f":"七言绝句","c":["东海边来南海边，长亭三百路三千。","飘零到此成何事，结得梅花一笑缘。"]},{"t":"题梅岭云封四绝 其二","f":"七言绝句","c":["淮南得道岭南行，岭上回头作么生。","传得祖师心印了，钵盂何必与人争。"]},{"t":"题黄州谢深道国正山庵","f":"七言绝句","c":["就荒山竹重抽笋，新种池荷晚著花。","意象全然似村落，又添茅屋两三家。"]},{"t":"衡阳舟中","f":"七言绝句","c":["萧萧风雨送行舟，小泊垂杨古渡头。","不忍缓行江上路，落梅片片是诗愁。"]},{"t":"赠饶叔虎谈易论命多奇中","f":"七言绝句","c":["中年多病早衰翁，诗不能工枉受穷。","郊岛五行君识否，要知我命与渠同。"]},{"t":"赣州上清道院呈姚雪蓬","f":"七言绝句","c":["短墙不碍远山青，无事烧香读道经。","时把一杯非好饮，客怀宜醉不宜醒。"]},{"t":"一冬无雨雪而有雷","f":"五言律诗","c":["万物久如渴，三冬一向晴。","时无腊雪下，夜有瑞雷鸣。","休咎占天意，悲欢见物情。","山禽何所感，烂熳作春声。"]},{"t":"一老儒为贵人烧丹丹垂成而走因此失所","f":"五言律诗","c":["道途多险阻，此老欲何之。","命薄丹砂走，天寒白发悲。","从教达官骂，忍受小儿欺。","月夜双乌鹊，飞鸣绕树枝。"]},{"t":"一相识无辜获罪","f":"七言律诗","c":["一宿津亭睡不成，愁来物物是离情。","月轮高挂山河影，江浪巧为风雨声。","志士失涂为鬼笑，佳人泣血送君行。","塞翁得马非为福，公论如天久自明。"]},{"t":"一笑","f":"五言律诗","c":["海曲荒凉地，吟边蹭蹬身。","时危法当隐，年老惯居贫。","俗客苦恋坐，小孙痴弄人。","等闲成一笑，不觉把杯频。"]},{"t":"九日","f":"五言律诗","c":["今日知何日，他乡忆故乡。","黄花一杯酒，白发几重阳。","日晚鸦争宿，天寒雁叫霜。","客中无此醉，何以敌凄凉。"]},{"t":"九日登裴公亭得无灾可避自登山之句何季皋滕审言为之击节足以成篇","f":"七言律诗","c":["良辰乐事两相关，不可不求今日閒。","有酒能赊堪荐菊，无灾可避自登山。","心怀屈贾千年上，身在潇湘八景间。","好向樽前开笑口，人生枉自作愁颜。"]},{"t":"九日槠洲舟中","f":"七言律诗","c":["几年重九客他州，少泊槠田古渡头。","人向饮中言我乐，谁知笑里是吾愁。","黄华可忍抛三径，白发犹堪柰几秋。","今日登高无处所，一樽携上枕江楼。"]},{"t":"九月七日江上阻风","f":"五言律诗","c":["舣棹依乔木，扶筇涉浅沙。","云山多态度，水月两光华。","白首吟诗客，青帘卖酒家。","明朝风不定，来此醉黄花。"]},{"t":"人不聊生梅柳早有春意","f":"五言律诗","c":["岁歉家家窘，时危事事难。","出门如有碍，对酒亦无欢。","杨柳含春思，梅花耐岁寒。","少须天意转，谷熟万民安。"]},{"t":"人日","f":"七言律诗","c":["自换端平新历日，眼看日月倍光辉。","南州有雪古来少，人日不阴今见稀。","鼓舞万方观德化，转移一世属天机。","朝廷有道吾君圣，办作升平老布衣。"]},{"t":"又送行二首 其二","f":"五言律诗","c":["荆门在何许，鄂渚小踌躇。","宿处好看剑，客中宜读书。","交游天作合，江汉景何如。","窗户半天上，南楼好寓居。"]},{"t":"又送行二首 其一","f":"五言律诗","c":["荏苒岁云暮，雪霜天正寒。","取程毋太急，御下放教宽。","朝夕去家远，关山行路难。","边头办功业，恐不在儒冠。"]},{"t":"万安江上","f":"七言律诗","c":["不能成佛不能仙，虚度人间六十年。","镜里姿容虽老矣，酒边意气尚飘然。","安排玉白花红句，趁办橙黄橘绿天。","无柰秋风动归兴，明朝问讯下江船。"]},{"t":"万安县芙蓉峰","f":"七言律诗","c":["凌空杰阁为谁开，隔岸芙蓉不用栽。","今古相传彩云现，江山曾识大苏来。","酒边歌舞共一笑，客里登临能几回。","翠浪玉虹从此去，明朝人在郁孤台。"]},{"t":"万杉长老秀痴翁见示五言次韵","f":"五言律诗","c":["了得宗门事，何忧常住贫。","听师林下话，是我眼中人。","星渚三秋月，庐山万古春。","昭陵御书在，岁久莫生尘。"]},{"t":"三山林唐杰潘庭坚张农师会于丁岩仲新楼","f":"七言律诗","c":["又携诗卷到南州，尘满征衫雪满头。","桃李春风故园梦，江山落日异乡愁。","樽前一笑真奇事，坐上诸君尽胜流。","政倚清谈洗胸臆，莫教王粲赋登楼。"]},{"t":"上乔右司","f":"五言律诗","c":["端笏立朝日，肺肝倾上前。","把麾持节处，桃李满淮壖。","药石箴时病，蓍龟烛事先。","焦头与曲突，为计孰为贤。"]},{"t":"上封","f":"五言律诗","c":["楼台逼霄汉，窗户纳云霓。","回顾千岩路，如登万仞梯。","泉从山顶出，雪压树头低。","高绝无人境，非僧不可栖。"]},{"t":"与侄南隐等赓和","f":"七言律诗","c":["梦回啼鸟聒幽棂，古篆香烟结画屏。","谈麈一挥尘事少，离骚才读醉魂醒。","闲居便是人间乐，克己何须座右铭。","但了耕桑□门户，我生安分合宁馨。"]},{"t":"久客还乡","f":"七言律诗","c":["短檐纱帽旧麻衣，铁杖扶衰步履迟。","老去分为无用物，客游谁道有归时。","丰年村落家家酒，秋日楼台处处诗。","生长此方真乐土，江淮百姓政流离。"]},{"t":"口号送椰心簟刘使君","f":"五言律诗","c":["适有椰心席，慇勤持赠君。","来从三屿国，织作五花文。","凉暖宜冬夏，清光隔垢氛。","桃笙与蕲簟，优劣迥然分。"]},{"t":"大龙湫","f":"五言律诗","c":["百丈云岩上，神龙噀水飞。","四时作风雨，万斛泻珠玑。","不可形容处，无穷造化机。","非他瀑布比，对此欲忘归。"]},{"t":"子渊送牡丹","f":"五言律诗","c":["有酒何孤我，因花赋恼公。","可怜秋鬓白，羞见牡丹红。","海上盟鸥客，人间失马翁。","不知衰病后，禁得几春风。"]},{"t":"小园","f":"五言律诗","c":["小园春欲半，老子作儿嬉。","政喜花开蚤，还愁客到迟。","诗当得意处，酒到半酣时。","蜂蝶来无数，无知却有知。"]},{"t":"小畦","f":"五言律诗","c":["小畦寻丈许，凿壁置柴扉。","雨后菜虫死，秋来花蝶稀。","插篱新种菊，抱瓮已忘机。","俗客忽相访，妨人洗布衣。"]},{"t":"山中少憩","f":"五言律诗","c":["地僻人稀到，山寒水欲冰。","闻钟知有寺，见犬不逢僧。","断垄森乔木，颓檐挂古藤。","斜阳照孤影，诗骨瘦崚嶒。"]},{"t":"山中见梅寄曾无疑","f":"七言律诗","c":["香动寒山寂寞滨，直从空谷见佳人。","树头树底参差雪，枝北枝南次第春。","有此瑰琦在岩壑，其他草树亦精神。","移根上苑谁云晚，桃李依然在后陈。"]},{"t":"山中即目二首 其二","f":"五言律诗","c":["茅屋七五聚，沙汀八九磐。","梯山畦麦秀，囊石障溪湍。","父老鸡豚社，儿童梨栗盘。","幽居有馀乐，奔走愧儒冠。"]},{"t":"山中即目二首 其一","f":"五言律诗","c":["岩路穿黄落，人家隐翠微。","笼鸡为鸭抱，网犬逐鹑飞。","竹好堪延客，溪清欲浣衣。","禅扉在何许，僧笠戴云归。"]},{"t":"山中夜归","f":"五言律诗","c":["落尽一林月，山中夜半归。","惊行群犬吠，破暗一萤飞。","举我赤藤杖，敲君白板扉。","兴来眠不得，吟到晓星稀。"]},{"t":"山行","f":"五言律诗","c":["度岭休骑马，临渊看网鱼。","木根高可坐，岩石细堪书。","谷鸟鸣相答，山云卷复舒。","儒衣人卖酒，疑是马相如。"]},{"t":"山行遇秀痴翁","f":"七言律诗","c":["新冬行乐赏新晴，几个江湖旧友朋。","霜蟹得橙同臭味，梅花与菊作交承。","樽前尽是论文客，林下那逢好事僧。","机解到时言语别，李翱诗句入传灯。"]},{"t":"广东漕李实夫四首 其四","f":"五言律诗","c":["忘家甘旅食，忧国属愁颜。","有客佩金印，何人守玉关。","风霜晚秋后，天地夕阳间。","痛洒伤时泪，别公归故山。"]},{"t":"广东漕李实夫四首 其三","f":"五言律诗","c":["千里长城手，如何在广州。","共谈天下事，莫上斗南楼。","瘦露封侯骨，忠怀报国秋。","丁宁北来雁，边信怕沉浮。"]},{"t":"广东漕李实夫四首 其二","f":"五言律诗","c":["志士规模远，非时展布难。","莫言南地暖，须念北风寒。","楮贱伤财力，兵骄稔祸端。","盛衰关气数，天下几时安。"]},{"t":"广东漕李实夫四首 其一","f":"五言律诗","c":["乾坤虽广大，人物不能多。","议论还诸老，文章自一科。","从横负才略，缓急任干戈。","不有济时杰，其如世事何。"]},{"t":"广州所见","f":"五言古诗","c":["风波行险道，万里绝人烟。","几个下番客，经年渡海船。","人皆贪舶货，我独惜青钱。","□□□□□，留心禁漏川。"]},{"t":"中秋李漕冰壶燕集","f":"七言律诗","c":["诸亭环立一湖湾，区界无多眼界宽。","苍石传为伪刘物，绿波曾浴葛仙丹。","两边堤树四时碧，一片冰壶六月寒。","咫尺云烟接沧海，须知此地有龙蟠。"]},{"t":"为石云悼鹤","f":"五言律诗","c":["瘗鹤有故事，花边结小茔。","不登千岁寿，无复九皋鸣。","问汝缘何死，主翁无限情。","最令人忆处，侧耳听松声。"]},{"t":"为客","f":"五言律诗","c":["琴剑长为客，诗书欠策勋。","老来临镜懒，愁里把杯勤。","北雁寒离塞，秋鹰健拂云。","物情能奋发，人不解超群。"]},{"t":"乌聊山登览","f":"七言律诗","c":["抖擞嚣尘上翠微，旁溪寺上坐题诗。","忽闻啼鸟不知处，细看好山无厌时。","风扫云烟开远景，人携香火谒丛祠。","客来千里登临意，说与时人未必知。"]},{"t":"书事","f":"五言律诗","c":["两揆新当国，三边未解兵。","吾君极勤俭，天下望升平。","春雨随时下，福星连夜明。","寒儒卜天意，对酒百忧轻。"]},{"t":"书事","f":"五言律诗","c":["喜作羊城客，忘为鹤发翁。","问天求酒量，翻海洗诗穷。","已过西南道，适遭东北风。","扁舟载明月，枉作卖油公。"]},{"t":"元日二首呈永丰刘叔冶知县 其二","f":"五言律诗","c":["市近人声杂，窗明雨色开。","异乡轻度节，同邸重传杯。","不碍狂夫醉，知无贺客来。","故园归未得，茅屋想苍苔。"]},{"t":"元日二首呈永丰刘叔冶知县 其一","f":"五言律诗","c":["焚香拜元日，受岁客他州。","白发难遮老，新年讳说愁。","无人能访戴，有地足依刘。","桃李争春事，梅花笑未休。"]},{"t":"六月三日闻王鉴除殿前都虞候孟枢除夔路策应大使时制司籍定渔船守江甚急","f":"五言律诗","c":["闻说北风凛，其然其不然。","新除策应使，急点守江船。","设险浑无地，扶危赖有天。","吾皇自神武，北伐美周宣。"]},{"t":"凤凰台","f":"五言律诗","c":["登临舒老眼，吊古得凄凉。","故国自龙虎，高台无凤凰。","浮云多改变，乔木见兴亡。","往事浑休问，钟山又夕阳。"]},{"t":"化成岩","f":"五言律诗","c":["城郭嚣尘外，江山胜概中。","铿然一滩水，和以万松风。","夹径森奇石，危亭纳太空。","苍岩不能语，曾识赞皇公。"]},{"t":"友人朱渊出示廷对策不顾忌讳读之使人凛凛受淮东制置辟","f":"七言律诗","c":["龙墀射策对明君，忧国忠言骇见闻。","皎皎一心如白日，寥寥千古再朱云。","时危诸老皆求去，兵满三边未解纷。","要使文臣知武事，不妨王粲且从军。"]},{"t":"友松亭代松语","f":"七言律诗","c":["从来岩壑守孤踪，岂料移归宝籞中。","幸在交游一人数，愿勤培植百年功。","朱门纵有三千客，青眼毋忘十八公。","根本既深枝叶茂，相期直上碧霄中。"]},{"t":"壬寅岁旦景明子渊君玉携酒与诗为寿次韵","f":"五言律诗","c":["舍我白瓷椀，把君金屈卮。","判为元日醉，共赋早春诗。","冰泮鱼龙起，花开蜂蝶知。","为子扶病脚，赖有古藤枝。"]},{"t":"壬寅除夜","f":"五言律诗","c":["今夕知何夕，满堂灯烛光。","杜陵分岁了，贾岛祭诗忙。","横笛梅花老，传杯柏叶香。","明朝贺元日，政恐雨相妨。"]},{"t":"天竺访明上座","f":"五言律诗","c":["顾影良堪笑，胡为八尺长。","苍颜抗尘土，饿喙说兴亡。","竹雨先秋爽，松风生夜凉。","爱寻湖上寺，留宿赞公房。"]},{"t":"太湖县雪中简段子克知县","f":"五言律诗","c":["腊雪随风下，蹇驴行路难。","匆匆投邸舍，草草共杯盘。","喜见丰年瑞，浑忘昨夜寒。","儿童不解事，却作柳花看。"]},{"t":"少算","f":"七言律诗","c":["吾生落落果何为，世事纷纷无了期。","少算人皆嘲我拙，多求我却笑人痴。","庭花密密疏疏蕊，溪柳长长短短枝。","万事欲齐齐不得，天机政在不齐时。"]},{"t":"斗山子王深父作石屏记为老夫书其文甚佳采记中语作五诗致谢 其四","f":"五言律诗","c":["细读石屏记，堪嗟老病身。","谁知饥欲死，曷取寿长贫。","雪片丰年瑞，梅花腊月春。","今朝一杯酒，谁道是生辰。"]},{"t":"斗山子王深父作石屏记为老夫书其文甚佳采记中语作五诗致谢 其五","f":"五言律诗","c":["细读石屏记，多君才思清。","南山数峰碧，北斗七星明。","风土钟奇秀，文章到老成。","待看黄鹄举，唾手取功名。"]},{"t":"斗山子王深父作石屏记为老夫书其文甚佳采记中语作五诗致谢 其二","f":"五言律诗","c":["细读石屏记，诚然愧我心。","兰荪借芳馥，金石假声音。","俗子方腾谤，朋俦合献箴。","分为无用物，白发委山林。"]},{"t":"斗山子王深父作石屏记为老夫书其文甚佳采记中语作五诗致谢 其三","f":"五言律诗","c":["细读石屏记，寻幽到水涯。","老人相问答，属意在岩花。","江海浮天阔，山林去国赊。","草茅最深处，认作野人家。"]},{"t":"斗山子王深父作石屏记为老夫书其文甚佳采记中语作五诗致谢 其一","f":"五言律诗","c":["细读石屏记，临风觉厚颜。","如何一片石，欲比众名山。","浪迹江湖上，归身岩壑间。","渔樵争半席，人笑老痴顽。"]},{"t":"方孚若真□宅堂前池上作淮南小山题咏者甚多见其诗轴次韵","f":"七言律诗","c":["妙手能移造化功，壶中幻出九华峰。","山虽云小能栖凤，水不求深贵有龙。","事纪淮南千古胜，记成嘉泰八年冬。","先生不用赋招隐，办了功名访赤松。"]},{"t":"无为山中郑老家","f":"七言律诗","c":["高谈可听用心幽，灼见此翁非俗流。","鞍马破家还避世，田园得地肯封侯。","开窗脩竹无由俗，绕屋青山总是秋。","门外短篱看亦好，黄金菊间碧牵牛。"]},{"t":"无为军界上遇太湖赵尉制府禀议","f":"五言律诗","c":["解后风尘底，周旋鞍马间。","三杯送行色，一笑强开颜。","夜宿煖汤市，晨炊冷水关。","军前献筹策，第一守光山。"]},{"t":"无策","f":"五言律诗","c":["老觉登楼懒，心知涉世疏。","梦蕉还得鹿，缘木可求鱼。","晚岁未闻道，平生欠读书。","行藏两无策，究竟果何如。"]},{"t":"月夜怀董叔宏闻其入京未得振","f":"五言律诗","c":["酒醒兴未已，诗成吟不休。","一凉风满座，半夜月明楼。","老骥思千里，飞鸿阅九州。","故人何处在，谁作置书邮。"]},{"t":"水陆寺","f":"五言律诗","c":["长沙沙上寺，突兀古楼台。","四面水光合，一边山影来。","静分僧榻坐，晚趁钓船回。","明日重相约，前村访早梅。"]},{"t":"王应求出示蜀中山水障气势甚雄伟李巽岩题其后论其画笔之源流二百馀字","f":"五言律诗","c":["妙甚丹青手，能移造化功。","三川山水国，半幅画图中。","玉局人何在，铜梁路可通。","巽岩扛鼎笔，文与画争雄。"]},{"t":"王和甫主簿卜地改葬双亲一夕梦到一处风水佳甚及到雁荡罗汉寺后山宛如梦中所见及造圹众石之中独有一穴仅可容双棺孝感如此","f":"七言律诗","c":["仇香竭力奉双亲，孝感于天得此坟。","众石中藏一抔土，来山面对五峰云。","龟鸾远近参差见，龙虎低昂左右分。","早见凌云牡丹现，他年朱紫定纷纷。"]},{"t":"王深道奏名而归","f":"五言律诗","c":["忠言犯时忌，决不中高科。","一日成名了，诸公属望多。","还家宁久住，经世欲如何。","西涧一泓水，行通沧海波。"]},{"t":"见名园荒废有感","f":"五言律诗","c":["乔木无留影，残花尚假妍。","荒池蛙叫噪，破屋燕周旋。","富贵偏多事，风流得几年。","墙东有寒士，书种世相传。"]},{"t":"见江东绣衣袁广微","f":"五言律诗","c":["宇宙归微数，安危委大臣。","金门一回首，玉节久临民。","雅志思行古，清风不受尘。","洁斋家学旧，用处日如新。"]},{"t":"见赵知道运使","f":"五言律诗","c":["饱食武昌鱼，不如归故庐。","盟鸥还海道，问雁觅家书。","又把乡人刺，来投使者车。","东园桃与李，莫使著花疏。"]},{"t":"见淮东制帅赵南仲侍郎相待厚甚特送买山钱又欲刊石屏诗置于扬州郡斋话别叙谢","f":"七言律诗","c":["如公当向古人求，识面何须万户侯。","浪说钓鳌游瀚海，真成骑鹤上扬州。","受恩多处难为别，宿酒醒时始觉愁。","回首平山堂下路，不堪风雨送归舟。"]},{"t":"见曾提刑兼安抚","f":"七言律诗","c":["传家学术用如新，风采英英照七闽。","澄按并开都督府，平反专奉太夫人。","关河未定心忧国，麾节相仍泽在民。","闻说青云多故旧，不应久作外台臣。"]},{"t":"见湖南绣使陈益甫大著 其一","f":"五言律诗","c":["手揽澄清辔，声名汉范滂。","一台振风采，列郡正权纲。","衡岳势增重，文星日有光。","金门虽藐藐，玉节自堂堂。"]},{"t":"见湖南绣使陈益甫大著 其二","f":"五言律诗","c":["麾节罗群彦，朝廷只数公。","近民多惠泽，望阙负孤忠。","星殒京城震，沙移海水通。","欲知休咎證，无路问苍穹。"]},{"t":"见湖南绣使陈益甫大著 其三","f":"五言律诗","c":["敢写散人号，来登君子堂。","论文才力短，忧世话头长。","老不堪行路，心思归故乡。","数行诗后语，夜夜吐光芒。"]},{"t":"长汀寄李使君","f":"五言律诗","c":["在处晚禾熟，经今瘴雾消。","山林无盗贼，道路有歌谣。","人喜逢丰岁，谁知感圣朝。","溪桥闲寓目，鱼鸟亦逍遥。"]},{"t":"长沙有感","f":"五言律诗","c":["自饮长沙酒，春风几醉醒。","江波随意绿，山色为谁青。","鸟好因人好，龟灵不己灵。","江蓠与杜若，何幸入骚经。"]},{"t":"长沙呈赵东岩运使并简幕中杨唯叔通判诸丈","f":"七言律诗","c":["日莫远涂行未休，白头又作长沙游。","湘江一点不容俗，岳麓四时皆是秋。","香草汀洲付骚客，红莲幕府聚名流。","吟边万象写不得，上有风流赵倚楼。"]},{"t":"长沙道上","f":"五言律诗","c":["诗情满天地，客梦绕潇湘。","何处桂花发，秋风昨夜香。","登山犹矍铄，照水见昂藏。","未了一生事，难禁两鬓霜。"]},{"t":"风雨无憀中览镜有感作小诗未有断句适两侄孙携诗卷来","f":"五言律诗","c":["览镜忽有感，谁能写我真。","崚嶒忍饥面，蹭蹬苦吟身。","风叶飘零夜，雨花狼藉春。","相过慰牢落，吾族有诗人。"]},{"t":"东谷王子文死读其诗文有感","f":"五言律诗","c":["东谷今何在，骑鲸去渺茫。","荆花半零落，岩桂自芬芳。","议论波澜阔，文章气脉长。","遗编犹可考，何必计存亡。"]},{"t":"东轩","f":"五言律诗","c":["东轩亦潇洒，春晚雨晴时。","喜鹊立门限，飞花落砚池。","青山解留客，绿竹遍题诗。","一点归心动，夜来闻子规。"]},{"t":"代人送别","f":"五言律诗","c":["南浦春波碧，东风送客船。","别君杨柳外，挥泪杏花前。","粉壁题诗句，金钗当酒钱。","一声离岸橹，心碎楚江边。"]},{"t":"代书寄韩履善右司赵庶可寺簿 其三","f":"五言律诗","c":["闭户生涯薄，忧时念虑长。","老犹思汗漫，贫已在膏肓。","弱柳饶春色，幽兰抱国香。","穷通安我命，一笑且持觞。"]},{"t":"代书寄韩履善右司赵庶可寺簿 其一","f":"五言律诗","c":["懒不脩书札，将诗问起居。","升沉元自异，故旧忍相疏。","学术有馀用，班行不次除。","功名付公等，世道莫愁予。"]},{"t":"代书寄韩履善右司赵庶可寺簿 其二","f":"五言律诗","c":["涉世几三折，行年近八旬。","江湖倦游客，天地苦吟身。","白发可怜老，青云多故人。","东风虽有力，朽木不逢春。"]},{"t":"冬日移舟入峡避风","f":"五言律诗","c":["棹入黄芦浦，惊飞白鹭群。","霜华浓似雪，水气盛于云。","市远炭增价，天寒酒策勋。","同舟有佳士，拥被共论文。"]},{"t":"冬暖","f":"五言律诗","c":["天不雨霜雪，朝曦与暮霞。","江梅迟腊蕊，岩桂更冬花。","地暖宜为客，时难重忆家。","楚山当晚眺，归兴逐栖鸦。"]},{"t":"卢申之正字小酌","f":"五言律诗","c":["清境无尘杂，羁怀向此开。","主人有风度，和我不尘埃。","倚竹评诗句，拈花泛酒杯。","出门见明月，客去又招回。"]},{"t":"去年访曾幼卿通判携歌舞者同游凤山仆有歌舞不容人不醉樽前方见董娇娆之句今岁到凤山又辟西隅筑堤种柳新作数亭且欲建藏书阁后堂佳丽皆屏去之矣仆嘉其志又有数语并录之 其二","f":"七言律诗","c":["别驾常怀物外心，黄金屡费买山林。","后堂不肯著歌舞，高阁唯思贮古今。","几处亭台新结束，一春风雨阻登临。","野夫昨日闲乘兴，著屐寻诗到柳阴。"]},{"t":"古田县行览呈刘无竞","f":"七言律诗","c":["客游花县自逍遥，百里风光在两桥。","语出桑阴鸠妇喜，身穿麦秀雉雏娇。","青山一任云来去，绿水多为风动摇。","上下相安长官好，野亭闲坐听民谣。"]},{"t":"史贤良入蜀有锦江诗卷陈谊甚高","f":"五言律诗","c":["学道世情薄，论交谊气深。","谩怀三献玉，肯受四知金。","万里铜梁道，千篇锦水吟。","一芹供匕箸，聊寓野人心。"]},{"t":"叶宗裔为令叔求竹山诗 其二","f":"七言律诗","c":["一景分明似渭川，竹山堂好以人贤。","兰亭价为羲之重，岘首名因叔子传。","紫翠数峰长在眼，琅玕万个欲参天。","老夫身堕尘埃底，遥挹清风亦洒然。"]},{"t":"叶宗裔为令叔求竹山诗 其一","f":"七言律诗","c":["爱竹旧称王子猷，今君异世等风流。","山中便是清凉国，门下合封潇洒侯。","有此一堂真可隐，不妨诸侄与同游。","吟边想像参差绿，许我携琴一到不。"]},{"t":"处世","f":"七言律诗","c":["风波境界立身难，处世规模要放宽。","万事尽从忙里错，一心须向静中安。","路当平处经行稳，人有常情耐久看。","直到始终无悔吝，旁生枝叶便多端。"]},{"t":"平江呈毅夫侍郎","f":"七言律诗","c":["龙墀射策三千字，未抵胸中十万兵。","远大无过为将相，文章争似立功名。","当今天下几豪杰，独数君家两弟兄。","世事从横人事左，未知何以措升平。"]},{"t":"归后遣书问讯李敷文 其三","f":"五言律诗","c":["闻说营新第，无从贺落成。","门庭山水色，楼阁管弦声。","海内二三杰，胸中十万兵。","宁为一区计，不使九州平。"]},{"t":"归后遣书问讯李敷文 其四","f":"五言律诗","c":["忆作南州客，归来东海滨。","尚怀忧世志，忍说在家贫。","老作山林计，梦随车马尘。","郁孤台上月，无复照诗人。"]},{"t":"归后遣书问讯李敷文 其一","f":"五言律诗","c":["绣斧离章贡，旋闻帅寿沙。","先生方易节，客子已还家。","别后仙凡隔，归来道路赊。","秋风两行字，也胜寄梅花。"]},{"t":"归后遣书问讯李敷文 其二","f":"五言律诗","c":["身退谋家易，时危致主难。","才能今管乐，人物旧张韩。","吾国日以小，边疆风正寒。","平生倚天剑，终待斩楼兰。"]},{"t":"归舟已具李宪楼仓有约盗贼梗道见避乱者可怜 其一","f":"五言律诗","c":["岁律又云莫，临风咏式微。","两台方有约，一棹未成归。","夜宿三家市，天寒百衲衣。","豺狼当道路，鸥鹭亦惊飞。"]},{"t":"归来二首儿子创小楼以安老者 其一","f":"五言律诗","c":["老去知无用，归来得自如。","几年眠客舍，今日爱吾庐。","处世无长策，闲时读故书。","但能营一饱，浑莫问其馀。"]},{"t":"归来二首儿子创小楼以安老者 其二","f":"五言律诗","c":["破屋不可住，如何著老身。","喜于乔木下，见此小楼新。","山好如佳客，吾归作主人。","摩挲双脚底，无复踏红尘。"]},{"t":"戊戌冬","f":"五言律诗","c":["造化人难测，寒时暖似春。","蛟龙冬不蛰，雷电夜惊人。","四海疮痍甚，三边战伐频。","静中观气数，愁杀草茅臣。"]},{"t":"永新宰潘仁叔再约观梅","f":"七言律诗","c":["去年忆访潘怀县，樽俎风流主意饶。","爆竹声中度残岁，华灯影里醉元宵。","春风又起观梅兴，野客仍烦折简招。","预想张园寻故事，插花秉烛过溪桥。"]},{"t":"永新彭时甫馆仆于玉峰楼龙子崇来话旧","f":"五言律诗","c":["暂舣溪头棹，来敲月下门。","江湖十年别，故旧几人存。","听雨夜同榻，论心酒一樽。","不须谈世事，万虑满乾坤。"]},{"t":"汉阳登览呈王中甫使君","f":"七言律诗","c":["西州城郭虽然小，江汉规模壮矣哉。","大别山头观禹迹，楚波亭上望吴台。","萧萧修竹凤不至，漠漠平沙雁又来。","五马相邀共登览，欲酬秋兴费诗材。"]},{"t":"玉山章泉本章氏所居赵昌甫迁居于此章泉之名遂显","f":"五言律诗","c":["兹山自开辟，有此一泓泉。","姓自章而立，名因赵以传。","源从番水出，地与瑞峰连。","寄语山中友，临流著数椽。"]},{"t":"生朝对雪张子善有词为寿","f":"五言律诗","c":["焚香拜天贶，满眼是瑰琦。","腊月雪三尺，春风梅数枝。","登楼忘老态，对酒展秋眉。","争唱阳春曲，山翁醉不知。"]},{"t":"田园吟","f":"七言律诗","c":["自古田园活计长，醉敲牛角取宫商。","催耕啼后新秧绿，锻磨鸣时大麦黄。","桐树著花茶户富，梅林无实秫田荒。","狂夫本是农家子，抛却一犁游四方。"]},{"t":"白鹤观","f":"五言律诗","c":["荒径行如错，蟠松看转奇。","鸟声人静处，山色雨晴时。","赊得溪翁酒，閒寻道士棋。","个中有佳趣，莫怪下山迟。"]},{"t":"石亭野老家","f":"七言律诗","c":["野老将余到石亭，先呼小豹出相迎。","依凭林谷住家稳，奔走儿童见客惊。","牛豕与人争径路，桑麻绕屋蔽柴荆。","溪边不合栽桃李，犹恐春风惹世情。"]},{"t":"石屏久游湖海祖妣遂题二句于壁云机番白苧和愁织门掩黄花带恨吟后石屏归祖妣已亡矣续成一律","f":"七言律诗","c":["伊昔天边望藁砧，天边鱼雁几浮沉。","机番白苧和愁织，门掩黄花带恨吟。","自古诗人皆浪迹，谁知贤妇有关心。","归来却抱双雏哭，碑刻虽深恨更深。"]},{"t":"石洲遇陈季申话旧","f":"五言律诗","c":["绿树挂乌帽，清波照白头。","合随秋燕去，那作贾胡留。","红吐槟榔唾，香薰茉莉毬。","樽前话畴昔，一笑不能休。"]},{"t":"立春后二首 其二","f":"五言律诗","c":["东风吹竹屋，无数落梅花。","冻雀栖檐角，饥乌啄草芽。","家乡劳夜梦，客路又春华。","莫讶狂夫醉，西楼酒可赊。"]},{"t":"立春后二首 其一","f":"五言律诗","c":["夕望春风至，还经闰月迟。","梅花丈人行，柳色少年时。","爱酒常无伴，吟诗近得师。","离骚变风雅，当效楚臣为。"]},{"t":"会心","f":"五言律诗","c":["我本江湖客，来观雁荡奇。","脚穿灵运履，口诵贯休诗。","景物与心会，山灵莫我知。","白云迷去路，临水坐多时。"]},{"t":"会李择之其父名丙字南仲著丁未录丙申录","f":"五言律诗","c":["吟边逢李白，谈笑亦风流。","相对各青眼，安知有白头。","两家穷活计，四海老交游。","不负云山约，同登百尺楼。"]},{"t":"先人东皋子小园七言人多喜之浼秋房楼大卿作大字刻石","f":"五言律诗","c":["父殁名随泯，诗存世莫传。","敢求大手笔，为写小园篇。","词翰成双美，光华照九泉。","托公垂不朽，镌刻到千年。"]},{"t":"光泽溪上","f":"五言律诗","c":["舣棹西岩下，舟人语夜阑。","风林无鸟宿，石窟有龙蟠。","月色连沙白，滩声入梦寒。","晓来新得句，寄与故人看。"]},{"t":"兴国军晚春简吴提干","f":"七言律诗","c":["几夜林间哭杜鹃，东风又作落花天。","青春不觉过三月，白发谁能满百年。","日射江波光闪闪，天连烟草碧芊芊。","异乡欲作登楼赋，心逐归鸿到海边。"]},{"t":"再赋惜别呈李实夫运使","f":"七言律诗","c":["一生飘泊老江湖，今日别公归故庐。","此去怕无相见日，因风或有寄来书。","云烟过眼时时变，草树惊秋夜夜疏。","人物似公能几辈，不知天下竟何如。"]},{"t":"刘兴伯黄希宋苏希亮慧力寺避暑","f":"五言律诗","c":["何处避炎热，相期过宝坊。","万松深处坐，六月午时凉。","钟磬出深屋，江山界短墙。","醉来归兴懒，留宿赞公房。"]},{"t":"吉州李伯高会判送盐蠘子鱼比海味之珍者未免为鲈鱼动归兴","f":"七言律诗","c":["每思乡味必流涎，一物何能到我前。","怒奋两螯眸烱烱，饱吞三印腹便便。","形模突出盐池底，风味横生海峤边。","合为莼鲈动归兴，久抛东浦钓鱼船。"]},{"t":"吉州堆胜楼谢景周司理居其上","f":"七言律诗","c":["半天轮奂独嵬峨，遥望青原瞰碧螺。","纳纳乾坤森万象，重重洲渚绕层波。","诗情雅与江山合，酒兴偏于故旧多。","靴笏缚君难放浪，樽前狂客自高歌。"]},{"t":"同郑子野访王隐居","f":"七言律诗","c":["联骑来寻失马翁，相期投宿此山中。","一庭花影三更月，万壑松声半夜风。","共把酒杯眠不得，剧谈世事恨无穷。","明朝莫使儿童见，倘有江船吾欲东。"]},{"t":"同赵鼎臣游黄甫真人清虚庵","f":"五言律诗","c":["昨闻曹两府，河上遇游仙。","驻跸钱塘后，结庵庐阜边。","焚香观御帖，洗盏酌神泉。","雁足传书日，伤心已百年。"]},{"t":"同曾景建金陵登览","f":"五言律诗","c":["兴废从谁问，云烟过眼空。","吁嗟六朝事，想像半山翁。","百景饶君咏，三杯许我同。","登临无限意，多在夕阳中。"]},{"t":"孙季蕃死诸朝士葬之于西湖之上","f":"五言律诗","c":["卜宅西湖上，花翁死亦荣。","诙谐老方朔，旷达醉渊明。","风月生前梦，歌诗身后名。","风流不可见，肠断玉箫声。"]},{"t":"安丰倅李华被旨监军入闽讨贼华身督诸将先破贼巢穴所乡辄胜招捕使之成功监军之力居多守汀州四年民赖以安有应变压难之才仆游汀邵间实知其详为赋二首 其二","f":"七言律诗","c":["英雄疏略书生腐，守调如公天下无。","眼底纷纷付谈笑，胸中事事有规模。","从他要路争驰毂，独坐偏州再剖符。","平寇功成在谁手，乱山深处问樵夫。"]},{"t":"安丰倅李华被旨监军入闽讨贼华身督诸将先破贼巢穴所乡辄胜招捕使之成功监军之力居多守汀州四年民赖以安有应变压难之才仆游汀邵间实知其详为赋二首 其一","f":"七言律诗","c":["三年壮士起淮濆，贾勇从公定七闽。","在昔猩鼯中夜啸，而今桃李万山春。","临危性命轻如叶，破敌机锋妙若神。","自此南人不知反，使君还亦是天人。"]},{"t":"岁旦族党会拜","f":"五言律诗","c":["衣冠拜元日，樽俎对芳辰。","上下二百位，尊卑五世人。","排门乔木古，照水早梅春。","寒事将消歇，风光又一新。"]},{"t":"岁暮书怀寄林玉溪 其一","f":"五言律诗","c":["吾年几八十，暮景不胜斜。","老鹤犹能语，枯梅强作花。","一心为死计，无意问生涯。","有酒时相过，东邻八九家。"]},{"t":"岁暮书怀寄林玉溪 其二","f":"五言律诗","c":["笑共梅花语，穷难与命争。","人皆居燠馆，我独堕寒坑。","假合非吾道，幽栖了此生。","门墙元自静，群小莫从横。"]},{"t":"岁暮书怀寄林玉溪 其三","f":"五言律诗","c":["衮衮日不暇，看看岁又徂。","一生赋茅屋，几度换桃符。","天肯容吾老，人皆笑我迂。","玉溪何所见，时复问诗癯。"]},{"t":"岁暮呈真翰林","f":"五言律诗","c":["岁事朝朝迫，家书字字愁。","频沽深巷酒，独倚异乡楼。","诗骨梅花瘦，归心江水流。","狂谋渺无际，忍看大刀头。"]},{"t":"戏呈赵明府","f":"五言律诗","c":["堂堂附郭县，深远半如村。","能共斯民乐，浑忘太守尊。","梅花高可折，横浦挠无浑。","欠与诗狂者，清谈共一樽。"]},{"t":"扬州道宫安下制干朱行甫抚干方巨山连骑相访","f":"五言律诗","c":["道院群仙集，高轩二妙来。","文章清气足，谈笑老怀开。","落木三秋晚，黄花九日催。","何当陪胜践，共把蟹螯杯。"]},{"t":"有议袁蒙斋者","f":"七言律诗","c":["世上苦无公是非，讥评人物信犹疑。","镜中妍丑无私照，棋上高低有误时。","怀古尚馀乔木在，伤春唯许落花知。","黄金可办将何用，铸出当年钟子期。"]},{"t":"有烹犊延客者食之有感","f":"五言律诗","c":["田家茧栗犊，小小可怜生。","未试一犁力，俄遭五鼎烹。","朝来占食指，妙绝此杯羹。","口腹为人累，终怀不忍情。"]},{"t":"有感","f":"五言律诗","c":["皱眉观世事，把酒读离骚。","天下无公论，胸中有古刀。","徒然成耿耿，何以制滔滔。","不逐群飞转，孤鸿毕竟高。"]},{"t":"有感","f":"七言律诗","c":["老子生来世法疏，白头思欲把犁锄。","摩挲此腹空无物，侥倖虚名愧有馀。","憔悴不堪渔父笑，寒温无益贵人书。","诗家幸有严华谷，襟谊犹能眷眷予。"]},{"t":"有感","f":"五言律诗","c":["浩浩海风劲，滔滔河水浑。","古人皆去世，乔木自当门。","族党诸孙盛，吾宗一线存。","兴衰知有数，心事与谁论。"]},{"t":"朱子昂司户登滕王阁","f":"七言律诗","c":["笑傲不禁秋兴长，登临谁复问滕王。","江湖周折地襟带，云霞粲烂天文章。","人如野鹤何飘逸，目送飞鸿去渺茫。","安得雪醅三百斗，发君豪气对吾狂。"]},{"t":"朱仲寔少府到官无几日即入佥幕官满送行二首 其二","f":"五言律诗","c":["孝友平生事，守廉天下难。","居官一日俸，阖室几人餐。","病骨何妨瘦，吟肩不肯寒。","功名未须问，且奉版舆安。"]},{"t":"朱仲寔少府到官无几日即入佥幕官满送行二首 其一","f":"五言律诗","c":["才智人难及，上官能用贤。","梅仙无一事，莲幕坐三年。","政誉倾千里，归途仰二天。","辟书闻早上，松菊莫留连。"]},{"t":"朱行父留度岁","f":"七言律诗","c":["衡山之下湘江上，风月留连去较迟。","四海弟兄多不遇，一门父子两相知。","梅边竹外三杯酒，岁尾年头几局棋。","羁旅宦游俱是客，细论心事共题诗。"]},{"t":"朱行甫和前韵送别烹鹿荐酒","f":"五言律诗","c":["此别真成别，从今去不来。","佳人难再得，恶抱向谁开。","客路一归晚，家书几度催。","慇勤见君意，烹鹿荐离杯。"]},{"t":"次韵史景望雪夜","f":"五言律诗","c":["雪中寒力壮，病骨瘦难胜。","温酒拨炉火，题诗敲砚冰。","惊心双白鬓，知我一青灯。","欲误浮生事，思参小大乘。"]},{"t":"次韵君玉春日","f":"五言律诗","c":["风雨不相贷，繁华能几时。","才歌喜晴赋，又作惜春诗。","压架酴醾老，翻阶芍药迟。","无花何足算，有酒且相期。"]},{"t":"次韵旴江李君昉见寄二首时李在包守郡斋 其二","f":"五言律诗","c":["共醉荆溪酒，不论杯浅深。","定交从此日，识面早知心。","久缺寒温问，忽闻长短吟。","玉霄亭下路，几夜梦相寻。"]},{"t":"次韵旴江李君昉见寄二首时李在包守郡斋 其一","f":"五言律诗","c":["久作丹丘客，疑君去复来。","高吟闯风雅，妙句斲琼瑰。","道谊心千古，文章水一杯。","荷花时话别，别后又梅开。"]},{"t":"次韵杜运使见赠","f":"七言律诗","c":["飘零敢说是诗人，故旧多居要路津。","穷贱交游谁复记，江湖踪迹早成陈。","无心涉世当归隐，有口逢人肯说贫。","家在翠屏山下住，茅庐虽小可容身。"]},{"t":"次韵陈叔强见寄 其二","f":"五言律诗","c":["穷通元有命，富贵柰无缘。","对此黄梅雨，歌君白雪篇。","风生三尺剑，梦逐五湖船。","白首成何事，归来敢问天。"]},{"t":"次韵陈叔强见寄 其一","f":"五言律诗","c":["识面者无数，论交要有缘。","未闻苍玉佩，先枉碧云篇。","采凤腾诗笔，持螯泛酒船。","山阴或乘兴，何待菊花天。"]},{"t":"次韵胡公权","f":"五言律诗","c":["日用无非道，人心实在平。","果能行实学，何必问虚名。","草木随时态，江山无世情。","晚来溪雨歇，一段夕阳明。"]},{"t":"次韵郡倅王子文小园咏春","f":"七言律诗","c":["州县徒劳喜近民，民间何事不关身。","谁知风月台中客，自是丝纶阁上人。","万缕绿垂杨柳雨，一梢红破海棠春。","小园暂作风光主，朝马行随辇路尘。"]},{"t":"次韵董叔宏山中有感","f":"五言律诗","c":["山中行乐处，百感上心来。","宿雾扫不去，好风吹自开。","岩花新得句，野水莫添杯。","不尽登临兴，扁舟棹月回。"]},{"t":"次韵谢敬之题南康县刘清老园","f":"五言律诗","c":["刘子隐居地，真如李愿盘。","万松春不老，多竹夏生寒。","卜筑世情远，登临客虑宽。","题诗疥君壁，聊以记游观。"]},{"t":"江上","f":"五言律诗","c":["山束江流急，云兼雾气深。","轻鸥闲态度，孤雁苦声音。","客路行无极，风光古又今。","梅花出篱落，幽事颇关心。"]},{"t":"江上","f":"五言律诗","c":["江上维舟稳，人间行路难。","数朝花雨细，一夜社风寒。","燕语能留客，蛙鸣岂为官。","苦吟成底事，赢得瘦团栾。"]},{"t":"江上","f":"五言律诗","c":["扁舟泊江渚，喜近酒家门。","出网鱼虾活，投林鸟雀喧。","无桥通竹处，有路到桃源。","一见南塘字，凄然忆故园。"]},{"t":"江上夜坐怀严仪卿李友山","f":"五言律诗","c":["江清天影动，楼近角声雄。","杨柳枝枝月，芭蕉叶叶风。","佳人难再得，良夜与谁同。","别后知何处，吟诗句句工。"]},{"t":"江山","f":"七言律诗","c":["借得茅楼一倚栏，见成诗句满江天。","归鸦啼处客投宿，野鸭飞边人上船。","老眼尚嫌随物转，闲心可惜被贫牵。","平生错做功名梦，金印何时二顷贤。"]},{"t":"江州德化县漪岚堂尽得庐山之胜醉中作此呈赵明府","f":"七言律诗","c":["不羡君为花县宰，羡君日坐漪岚堂。","有时酒兴兼诗兴，无限山光与水光。","百姓熙熙知教化，群胥凛凛对风霜。","公馀置酒看桃李，醉倒花前客自狂。"]},{"t":"江西壬辰秋大旱饥临江守王幼学监簿极力救民癸巳夏不雨几成荐饿监簿祷之甚切终有感于天 其二","f":"五言律诗","c":["天续饥民命，神知太守心。","骄旸化霖雨，六月借春阴。","早稻先秋熟，晚田储水深。","去年饥欲死，不料到于今。"]},{"t":"江西壬辰秋大旱饥临江守王幼学监簿极力救民癸巳夏不雨几成荐饿监簿祷之甚切终有感于天 其一","f":"五言律诗","c":["恳切金章奏，精诚玉帝知。","稻粱民性命，丰歉国安危。","苗秀方成实，雨来还及时。","人能合天意，天亦顺人为。"]},{"t":"江村何宏甫载酒过清江","f":"五言律诗","c":["玉笥千峰雨，金风十日秋。","谁能多载酒，来此共登楼。","山立阅万变，溪深纳众流。","故人归未得，我亦为诗留。"]},{"t":"江涨见移居者","f":"五言律诗","c":["夏潦连秋涨，人家水半门。","都抛破茅屋，移住小山村。","聒聒笼鸡犬，累累带子孙。","安居华屋者，应觉此身尊。"]},{"t":"江皋","f":"五言律诗","c":["江皋有闲客，独立对秋风。","白鸟来无数，青林望不穷。","斜阳方照晚，新月早腾空。","得句从谁语，倾心酒椀中。"]},{"t":"江滨晓步","f":"七言律诗","c":["津头晓步落潮痕，行尽蒲根到柳根。","雁影参差半江月，鸡声咿喔数家村。","求鱼看下连筒钓，乞火听敲邻舍门。","料得锦城无此景，欲将图画寄王孙。"]},{"t":"竹洲诸侄孙小集永嘉蒋子高有诗次韵","f":"七言律诗","c":["美景能兼乐事难，愁来唯仗酒遮拦。","昂藏病骨兼诗瘦，料峭春风带腊寒。","乔木尚疑前辈在，好花应笑老人看。","忍抛明月先归去，输与诸郎彻夜欢。"]},{"t":"约游曾参政西墅病不能去","f":"五言律诗","c":["骨肉去家远，异乡童仆亲。","老身浑赖汝，久病亦愁人。","无暇游西墅，寻医访北辰。","主翁翻作使，奔走莫劳神。"]},{"t":"自和前诗邻舟皆盐商","f":"五言律诗","c":["总被利名役，机心欲算沙。","舟行阻风色，客梦负年华。","洲渚四五曲，渔樵八九家。","江村无限好，满眼是芦花。"]},{"t":"自漳州回泉南主仆俱病","f":"五言律诗","c":["雅兴难忘酒，羁怀不耐秋。","坐穷思卖剑，扶病强登楼。","适有坐中客，来从边上州。","所谈惊老耳，身世并成忧。"]},{"t":"舟中","f":"五言律诗","c":["舣棹河梁畔，推篷得句新。","云为山态度，水借月精神。","密树藏飞翮，平波见跃鳞。","饥年村落底，也有醉归人。"]},{"t":"舟中","f":"五言律诗","c":["扁舟何处泊，沙渚夕阳边。","远浦横鱼网，高山起烧烟。","客行今老矣，秋思日凄然。","且复开怀抱，囊中有酒钱。"]},{"t":"舟中小酌","f":"五言律诗","c":["独立秋风里，怅然思故乡。","渚头沽美酒，船上作重阳。","篱菊一枝瘦，溪鱼三寸长。","客中聊尔耳，亦可慰凄凉。"]},{"t":"舟中夜坐","f":"五言律诗","c":["独坐观星斗，一襟秋思长。","天河司米价，太乙照时康。","月浦孤帆过，风荷一路香。","持杯问舟子，今夜宿谁乡。"]},{"t":"舟中病起登览","f":"五言律诗","c":["舣棹病三日，登楼举一觥。","江山从古在，花草逐时生。","南浦佳人别，西风送客行。","锦鳞能自跃，献我一杯羹。"]},{"t":"舟行往吊故人","f":"五言律诗","c":["乔木风声壮，大江天影圆。","悲秋时把酒，爱月夜行船。","未及到河上，先愁过竹边。","倚篷思往事，闻笛为凄然。"]},{"t":"舟行英德江上和许季如诗","f":"五言律诗","c":["趺坐篷窗底，客身无事时。","闲观曲江帖，因和许浑诗。","舟楫聊乘兴，溪山若献奇。","数峰英石美，天巧岂人为。"]},{"t":"观静江山水呈陈鲁叟漕使 其二","f":"五言律诗","c":["昨者登梅岭，兹来入桂林。","相从万里外，不负一生心。","湖上千峰立，樽前十客吟。","讥评到泉石，吾敢望知音。"]},{"t":"观静江山水呈陈鲁叟漕使 其一","f":"五言律诗","c":["桂林佳绝处，人道胜匡庐。","山好石骨露，洞多岩腹虚。","峥嵘势相敌，温厚气无馀。","可惜登临地，春风草木疏。"]},{"t":"许介之约过清溪道上有成","f":"五言律诗","c":["行尽白云际，乘槎过水西。","稻田秋后雀，茅舍午时鸡。","野饭自不恶，村醪亦可携。","闻钟欲投宿，何处是招提。"]},{"t":"许提干湖上下筑","f":"五言律诗","c":["才气有如许，功名不可无。","乐从闲岁月，养就大规模。","雅志难谐俗，幽居喜并湖。","君看莲下藕，不与叶同枯。"]},{"t":"访方子万使君宅有园林之胜","f":"五言律诗","c":["使君居处好，在郭却如村。","屋带园林胜，门无市井喧。","蛰龙将变化，雏凤亦腾鶱。","客里苦无暇，相从听雅言。"]},{"t":"访古田刘无竞","f":"五言律诗","c":["前说建阳宰，古田今似之。","难兄与难弟，能政更能诗。","文字定交久，江湖识面迟。","人传花萼集，俱受水心知。"]},{"t":"访西涧王深道 其二","f":"五言律诗","c":["诸老伤凋谢，凄凉属此时。","相从一夜语，忍读四哀诗。","世事生愁绪，秋风吹鬓丝。","黄花香晚节，说与秀岩知。"]},{"t":"访西涧王深道 其一","f":"五言律诗","c":["诸王居处僻，古屋满山坡。","传到宋淳祐，来从晋永和。","诗书历年久，名胜结交多。","一涧流芳润，滔滔秋水波。"]},{"t":"访严坦叔","f":"五言律诗","c":["麻姑山下泊，城郭带烟霞。","携刺投诗社，移船傍酒家。","沙禽时弄水，榉柳夏飞花。","小酌未能了，西楼日又斜。"]},{"t":"访张元德","f":"七言律诗","c":["今宵何幸宿书林，议论从横感慨深。","黄卷具传千古意，青灯照破几人心。","狂夫嗜饮夜偷酒，污吏容私昼攫金。","尧舜君民旧风俗，凡经几变到于今。"]},{"t":"访杨伯子监丞自白沙问路而去 其一","f":"五言律诗","c":["欲访扬雄宅，扁舟过白沙。","自从山以后，直到水之涯。","风节古人物，文章老作家。","相寻有忙事，第一问梅花。"]},{"t":"访杨伯子监丞自白沙问路而去 其二","f":"五言律诗","c":["朝市风波地，乾坤渔猎场。","生民日憔悴，吾道亦凄凉。","龙不为霖出，凤于何处藏。","群鸦争晚噪，一意送斜阳。"]},{"t":"访苍山曾子实","f":"五言律诗","c":["故人子曾子，居处近金精。","福地佳山水，诗家老弟兄。","十年重会面，一笑最关情。","万象亭前月，今宵为我明。"]},{"t":"访陈与机县尉于湘潭下摄市 其二","f":"五言律诗","c":["买得南坡景，创成西尉司。","宅幽连寺观，地广带亭池。","能事事易了，役民民不知。","题诗记颠末，政不假人碑。"]},{"t":"访陈与机县尉于湘潭下摄市 其三","f":"五言律诗","c":["吾里不识面，他乡喜见君。","数朝相款曲，杯酒接慇勤。","清挹湘江水，笑开衡岳云。","归心逐回雁，转首叹离群。"]},{"t":"访陈复斋寺丞于私第","f":"五言律诗","c":["以时为出处，真有古人风。","奉母易为孝，事君难尽忠。","閒居非傲世，直气尚摩空。","语及朝廷事，乾坤万感中。"]},{"t":"访赵东野","f":"七言律诗","c":["朅来问讯病维摩，花满溪堂竹满坡。","发秃齿危俱老矣，人高诗苦柰穷何。","四山便是清凉国，一室可为安乐窝。","犹有忧时两行泪，临风挥洒湿藤萝。"]},{"t":"访徐益夫","f":"五言律诗","c":["仲蔚蓬蒿宅，终朝只闭关。","无心与时竞，未老得身闲。","绿绕巡除水，青横隔岸山。","客来新酒熟，相对一酡颜。"]},{"t":"访曾云巢","f":"五言律诗","c":["一老今无恙，诸公昔与俦。","随时难苟合，怀道早归休。","苦似陶元亮，全如秦少游。","笔端锋锐别，有待续春秋。"]},{"t":"访曾鲁叔有少嫌先从金仙假榻长老作笋供","f":"五言律诗","c":["俗物败佳兴，余非后汝期。","既来迟一见，政恐错相疑。","同访金仙老，因参玉板师。","樽前有馀暇，细读放翁诗。"]},{"t":"访漳州赵用父使君","f":"七言律诗","c":["幸遇故人为太守，客来不惮路程遥。","九龙山水连沧海，五马声名动紫霄。","一意奉行宽大诏，多君不负圣明朝。","欲知惠爱及人处，听取街头卖炭谣。"]},{"t":"访慧林寺僧因有诗","f":"七言律诗","c":["故人有约访乡僧，少坐西林待晚晴。","双燕护雏更出入，群鸦攫肉斗飞鸣。","长溪积水流无尽，古木号风诉不平。","一段见成公案在，请君判断要分明。"]},{"t":"过三衢寻乡僧适遇爱山徐叔高同访郑监丞其家梅园甚佳选百家诗","f":"五言律诗","c":["暂作三衢客，寻僧出郭迟。","适逢徐孺子，同访郑当时。","诗集百家富，梅花几树奇。","匆匆又行役，不见烂柯棋。"]},{"t":"过昭武访李友山诗社诸人","f":"七言律诗","c":["吟过长亭复短亭，喜于溪上访诗朋。","雕锼已被天公怒，狂狷仍遭俗子憎。","故故愁人长夜雨，明明照我短檠灯。","休思京口相逢日，喜雨楼中赋大鹏。"]},{"t":"两山赵仁甫宰临安有武学生张丈相访酒边弄刀舞剑甚可观因成七言县乃钱王故宫九龙十锦皆其地","f":"七言律诗","c":["风流晋宋时人物，花县鸣琴调甚新。","不厌开樽留剑客，仍能下榻待诗人。","九龙池馆空陈迹，十锦山川自好春。","但见清吟度白日，不知佳政最宜民。"]},{"t":"何季皋司理故人也作诗见相勉意二首 其二","f":"五言律诗","c":["南州通外国，浊海溷清波。","人以廉称少，官从辟奏多。","持身宜洁白，事上莫依阿。","话别无他语，留心政事科。"]},{"t":"何季皋司理故人也作诗见相勉意二首 其一","f":"五言律诗","c":["梅花庾岭外，别是一山川。","那使民无讼，须知狱有冤。","心常存正直，法不尚平反。","于氏缘何事，阴功到子孙。"]},{"t":"余惠叔访旧","f":"七言律诗","c":["扁舟访旧入横塘，新柳今如旧柳长。","室迩人遥春寂寂，风流云散事茫茫。","纵题红叶随流水，谁弄青梅出短墙。","政是沈郎愁绝处，杜鹃不断叫斜阳。"]},{"t":"别后舟中用前韵","f":"七言律诗","c":["出郭风光便不同，转头犹恨去匆匆。","维舟别岸鸦啼后，倚柂澄江雁影中。","向老客怀惊岁月，乍寒天气转霜风。","冰壶亭上人如玉，谩寄篇诗不暇工。"]},{"t":"别李司直萧小山","f":"五言律诗","c":["老作五羊客，时从二妙游。","文星照南斗，吾道欲东周。","合作金闺彦，那为玉帐留。","严徐闻有召，吾亦办归舟。"]},{"t":"别邵武诸故人","f":"五言律诗","c":["白发乱纷纷，乡心逐海云。","此行堪一哭，无复见诸君。","老马寻归路，孤鸿恋旧群。","酒阑何处笛，今夜不堪闻。"]},{"t":"别钟子洪","f":"七言律诗","c":["识得潮阳钟子洪，今人可想古人风。","文章有气吞馀子，天地无情负此翁。","问舍求田非细事，参禅学佛见新功。","欲知别后真消息，莫惜频书寄海鸿。"]},{"t":"别章泉定庵二老人","f":"五言律诗","c":["腊里春风转，埙篪一气和。","劝翁新岁酒，唱我老人歌。","一世声名重，四方书问多。","章泉一泓水，思与海同波。"]},{"t":"别董叔宏兄弟","f":"五言律诗","c":["年老思家切，交深话别难。","扁舟行且止，尊酒强相宽。","客路归来晚，人情去后看。","西风吹过雁，千万寄平安。"]},{"t":"君玉同访岂潜饮间君度曼卿不约而至鹤方换翎羽出舞于桂花之下不可无语","f":"五言律诗","c":["秋来常日雨，雨霁忽秋深。","鹤换一身雪，花开满树金。","三杯动情性，一笑付园林。","莫怪先归去，衰翁薄疾侵。"]},{"t":"吴子似","f":"五言律诗","c":["载酒樱桃熟，隈亭柳树阴。","青山去人远，黄鸟话春深。","薄俗非吾道，虚名愧此心。","休言今不古，又恐不如今。"]},{"t":"吴子似提干九高亭小景","f":"七言律诗","c":["前日作诗题大概，亭前小景亦堪题。","绿杨树下茅三架，白水田头菜两畦。","似酒新鹅初泛浦，如孩黄犊试牵犁。","十分野趣关心事，到此令人忆剡溪。"]},{"t":"哭涧泉韩仲止二首 其二","f":"五言律诗","c":["忍贫长傲世，风节似君稀。","死后女方嫁，峡中儿未归。","门人集诗藁，故卒服麻衣。","涧上梅花发，吟魂何处飞。"]},{"t":"哭涧泉韩仲止二首 其一","f":"五言律诗","c":["雅志不同俗，休官二十年。","隐居溪上宅，清酌涧中泉。","慷慨伤时事，凄凉绝笔篇。","三篇遣稿在，当并史书传。"]},{"t":"吾乡陈万卿儒者能医见宜春赵守盛称其医药之妙著本草折衷可传","f":"五言律诗","c":["本草有折衷，儒医功用深。","何须九折臂，费尽一生心。","药物辨真伪，方书通古今。","有时能起虢，一剂直千金。"]},{"t":"吾族两派而下吾之一派衰落殆尽诸孙一两人而已其势不绝如线彼之一派富盛一日出门有感","f":"五言律诗","c":["门外长河水，有时鸣不平。","河边古樟树，亦各有枯荣。","人事关时数，春风莫世情。","贤哉沧海月，夜夜一般明。"]},{"t":"呈姚显叔奉亲送死极孝","f":"七言律诗","c":["雁去多年缺寄音，扁舟无复到山阴。","卧牛岗上经过少，下马陵前感慨深。","细读文公千字诔，足知孝子一生心。","无才为作招魂些，自有悲风宰树吟。"]},{"t":"呈赵园令","f":"七言律诗","c":["翠云屏嶂碧瑶池，万象前陈属指挥。","彷佛神仙居处好，寻常宾客到来稀。","荷花香里浑无暑，棋子声中却有机。","别院笙歌促君去，野夫自步月明归。"]},{"t":"庐山 其一","f":"七言律诗","c":["山灵未许到天池，又作西林一宿期。","寺是晋时陶侃宅，记传隋代率更碑。","山椒云气易为雨，客子情怀多费诗。","暂借蒲团学禅寂，茶烟飞绕鬓边丝。"]},{"t":"庐山 其二","f":"七言律诗","c":["道人问我看庐山，地上争如阁上看。","呈露千峰秋落木，雕锼万象客凭栏。","静中见得天机妙，闲里回观世路难。","管领风光有微憾，桂花香里酒瓶乾。"]},{"t":"庐山 其三","f":"七言律诗","c":["拥鼻行吟上下廊，今宵又宿赞公房。","松摇半夜风声壮，桂染中秋月色香。","白石清泉闻笑语，名山大泽出文章。","老夫甘作无名者，不逐纷纷举子忙。"]},{"t":"庐州帅李仲诗春风亭会客有尘字韵诗和者甚多韵拘无好语","f":"七言律诗","c":["玉关人老鬓丝新，千里长城在一身。","气使黄金结豪杰，手挥白羽静风尘。","山河四望亭中景，桃李一开天下春。","乡日满城骑战马，而今四野尽耕民。"]},{"t":"庐州界上寄丰帅","f":"五言律诗","c":["身健心先老，时危事愈乖。","无成携短剑，有恨满长淮。","村酒时时醉，山肴日日斋。","功名非我有，何处问生涯。"]},{"t":"庐陵城外","f":"五言律诗","c":["郭外人烟好，行行过北阡。","迎船分社肉，汲井种春田。","绿树前村路，黄梅细雨天。","客游乡土别，景物只同然。"]},{"t":"张子明索赋永斋诗诺之久矣杜撰四十字以还冷债","f":"五言律诗","c":["为学日不足，毋劳课近功。","声名垂不朽，文字用无穷。","草色朝朝碧，桃花岁岁红。","一机长运转，造物与人同。"]},{"t":"张仁仲提干衡阳冰壶亭燕客","f":"七言律诗","c":["大抵吾曹臭味同，留欢卜夜莫匆匆。","一亭景物冰壶上，万里乾坤玉镜中。","疏柳无心挂明月，败荷有恨倚西风。","吟家旧日张公子，千首诗成句句工。"]},{"t":"张统制之子为父求诗蕲州城破匹马打围而出能知数谓时不可为","f":"五言律诗","c":["夜半金城破，身随铁马飞。","横挥三尺剑，突出万人围。","勇锐资神力，功名与愿违。","自能占气数，终老著农衣。"]},{"t":"张端义应诏上书谪曲江正月一日赣州相遇 其二","f":"五言律诗","c":["正朝送迁客，好去看梅花。","此岭几人过，念君双鬓华。","直言知为国，远地莫思家。","韶石叫虞舜，伤哉古道赊。"]},{"t":"张端义应诏上书谪曲江正月一日赣州相遇 其一","f":"五言律诗","c":["忧世心何切，谋身计甚疏。","樽前话不尽，天下事何如。","汉武求言诏，贾生流涕书。","龙颜那可犯，谪向曲江居。"]},{"t":"怀江村何宏甫自赣上寄林檎","f":"五言律诗","c":["人好物亦好，交深谊转深。","他乡如对面，异体实同心。","未得平安报，相思长短吟。","无从回去马，有便寄来禽。"]},{"t":"怀何宏甫","f":"五言律诗","c":["何郎好兄弟，爱我往来频。","人作交游看，情如骨肉亲。","茅庵思共隐，蕙帐暖生春。","别后长相忆，寄书无便人。"]},{"t":"怀赵德行","f":"五言律诗","c":["所学源流远，澹交滋味长。","看来浑易与，别去自难忘。","独客梦千里，佳人天一方。","细观宾退录，亦足慰凄凉。"]},{"t":"怀雪蓬姚希声使君 其二","f":"七言律诗","c":["有感中来不自禁，短长亭下短长吟。","梅花差可强人意，竹叶安能醉我心。","世事无凭多改变，仕途相识半升沉。","摩挲老眼从头看，只有青山无古今。"]},{"t":"怀雪蓬姚希声使君 其一","f":"七言律诗","c":["寒入疏蓬夜雪深，是非难辩口如瘖。","一官不幸有奇祸，万事但求无愧心。","想像骑牛开画卷，丁宁回雁寄来音。","传家一首冰壶赋，未信横舟竟陆沉。"]},{"t":"投江西曾宪二首 其二","f":"五言律诗","c":["诸贤皆在位，治效尚迟迟。","污吏未能去，明君若可欺。","外台天耳目，正士国根基。","既揽澄清辔，那无按察时。"]},{"t":"投江西曾宪二首 其一","f":"五言律诗","c":["枢星居紫极，遥映使星明。","天下推名德，君家好弟兄。","一台振纲纪，列郡想风声。","不试褰帷手，官曹未易清。"]},{"t":"抚州节推萧学易衙宇一新","f":"七言律诗","c":["掇取高科如拾芥，爱君才调望君深。","莫誇书判居莲幕，要把文章入禁林。","华屋修成官满去，好诗改定客来吟。","西窗共对萧萧竹，不负三杯话此心。"]},{"t":"抚州谢楼宗丞见访","f":"七言律诗","c":["客里门庭可设罗，使君千骑肯相过。","心忘贵贱交游重，论及兴衰感慨多。","诸老逢时起岩壑，二边何日罢干戈。","老夫何预人间事，归去沧江理钓蓑。"]},{"t":"拟岘台杜子野主簿寓居","f":"五言律诗","c":["高台延望眼，风物满前村。","细读南丰记，频开北海樽。","远山如看画，近市不闻喧。","诗是君家事，长城在五言。"]},{"t":"李友山诸丈甚喜得朋留连日久月洲乃友山道号","f":"七言律诗","c":["此身到处自悠悠，一笑非为越女留。","风雨不妨鸡戒晓，江湖又见雁横秋。","途中有客居岩谷，天下何人似月洲。","颇欲相从溪上住，诸君许我卜邻否。"]},{"t":"李计使领客游白云景泰","f":"七言律诗","c":["天近刚风吹面寒，绣衣玉立白云间。","沧波万顷海南海，翠碧几重山外山。","自觉登临无限意，谁思富贵不如闲。","前峰若个神仙宅，指点烟霞见一斑。"]},{"t":"李司直会客吴运干有诗次韵","f":"七言律诗","c":["使君高会集群仙，也使狂夫坐细毡。","白璧一双酬议论，青春十载棹觥船。","客愁遇酒退三舍，梅信与春开一先。","已办扁舟明日去，几时重得到花前。"]},{"t":"李季允侍郎舟中","f":"七言律诗","c":["忆昨枫桥既语离，何期千里又相随。","太湖不见鸱夷子，秋浦同寻杜牧之。","灯火船窗深夜话，江山客路早冬诗。","人间草木空无数，除却梅花莫我知。"]},{"t":"李深道得苏养直所为深字韵一首不知题何处景俾跋其后","f":"七言律诗","c":["都来五十有六字，写出山林无限奇。","当日所题何处景，祇今但见后湖诗。","一言一语堪传世，某水某丘仍属谁。","试向愁烟推白鸟，无情白鸟又何知。"]},{"t":"杜子野主簿约客赋一诗为赠与仆一联云生就石桥罗汉面吟成雪屋阆仙诗","f":"七言律诗","c":["杜陵之后有孙耒，自守诗家法度严。","秀骨可仙官况薄，高情追古俗人嫌。","起看星斗夜推枕，为爱江山寒捲帘。","饱吃梅花吟更好，锦囊虽富不伤廉。"]},{"t":"杜门自遣","f":"七言律诗","c":["世事茫茫心事灰，众人争处我惊回。","闭门不管花开落，避俗唯通燕往来。","富贵在天求不得，光阴转地老相催。","平生任达陶元亮，千载神交共一杯。"]},{"t":"杜仲高自鄂渚下仪真","f":"五言律诗","c":["鄂渚三千里，南楼看月回。","东园花政好，去岁客重来。","兄弟皆名士，文章动上台。","倾城倾国色，也用觅良媒。"]},{"t":"杜仲高相遇约李尉","f":"七言律诗","c":["胸中无地著尘埃，有我唯堪把酒杯。","苦恨好山移不得，生憎俗客去还来。","秋风吹老东篱菊，春信搀开北岭梅。","管领风光须我辈，急吹短笛棹船回。"]},{"t":"杜仲高高九万相会","f":"五言律诗","c":["杜癖诗无敌，高髯画绝伦。","笑谈能不朽，富贵或成尘。","今古多奇事，乾坤几怪民。","相逢不容易，一醉楚江滨。"]},{"t":"杨伯子监丞霅川久雨得晴为喜","f":"七言律诗","c":["村南村北晒蓑衣，好是云开日出时。","太守少宽忧世志，野人为赋喜晴诗。","两岐瑞麦黄金实，八茧吴蚕白雪丝。","政事端知合天意，雨旸还亦顺人为。"]},{"t":"求安","f":"五言律诗","c":["愁来须强遣，老去只求安。","酒熟思招客，诗成胜得官。","梅花天下白，雪片夜深寒。","衲被蒙头睡，翛然百虑宽。"]},{"t":"汪见可约游青原","f":"七言律诗","c":["来访青原古钓矶，溪流衮衮濯龙奇。","一茶可款从僧话，数局争先对客棋。","云雨那能败吾事，山林政喜得君诗。","石头路滑篮舆小，换得扁舟在水湄。"]},{"t":"汪见可教授约诸丈凤山酌别","f":"七言律诗","c":["凤凰洲上凤凰山，草草登临见一斑。","不立樊墙天广大，剩栽花竹地宽闲。","白云四面峰千叠，绿柳前头水一湾。","行色催人诗未就，寄情庭院落花间。"]},{"t":"汪给事守鄂渚元宵代江夏宰吴熙仲献灯 其一","f":"七言律诗","c":["鄂州新得主人翁，今岁元宵便不同。","灯火夜深回昼日，管弦声动起春风。","辽天月借三秋白，陆地莲开十丈红。","妙手信能移造化，速宜归去补苍穹。"]},{"t":"汪给事守鄂渚元宵代江夏宰吴熙仲献灯 其二","f":"七言律诗","c":["一晴收尽四山云，天与黄堂作好春。","西楚东吴献风月，南楼北榭拥星辰。","扶持入郭观灯叟，歌舞拦街醉酒人。","此是太平真气象，今年第一个良辰。"]},{"t":"沈庄可号菊花山人即其所言","f":"五言律诗","c":["老貌非前日，清吟似旧时。","已无藏酒妇，幸有读书儿。","连岁修茅屋，三秋绕菊篱。","寒儒有奇遇，太守为刊诗。"]},{"t":"灵洲","f":"七言律诗","c":["一台中立郁苍苍，四面山光接水光。","潮信往来知气候，鼋精出没兆灾祥。","烟生茶灶僧留款，风展蒲帆客去忙。","白发东坡在何许，两行遗墨照琳琅。"]},{"t":"灵洲梅花","f":"七言律诗","c":["穿林傍水几平章，合有春风到草堂。","自入冬来多是暖，无寻花处却闻香。","枝南枝北一轮月，山后山前两履霜。","直看过年开未了，醉吟且放老夫狂。"]},{"t":"灵峰灵岩有天柱石屏之胜自昔号二灵","f":"五言律诗","c":["骇见二灵景，山林体势豪。","插空天柱壮，障日石屏高。","览胜苦不足，登危不惮劳。","白云飞动处，绝壁走猿猱。"]},{"t":"花朝侄孙子固家小集","f":"五言律诗","c":["今朝当社日，明日是花朝。","佳节唯宜饮，东池适见招。","绿深杨柳重，红透海棠娇。","自笑鬓边雪，多年不肯消。"]},{"t":"苏希亮约客游刘兴伯大自在亭","f":"五言律诗","c":["偶尔来江上，从君到酒边。","雨晴花弄日，风定柳凝烟。","适意共一笑，浮生无百年。","明朝大自在，谁办载花船。"]},{"t":"赤壁","f":"五言律诗","c":["千载周公瑾，如其在目前。","英风挥羽扇，烈火破楼船。","白鸟沧波上，黄州赤壁边。","长江酹明月，更忆老坡仙。"]},{"t":"辛丑岁暮三首 其三","f":"五言律诗","c":["意气久凋落，形模老可憎。","能扶双病脚，赖有一枯藤。","世味淡如水，吾心达似僧。","明朝今日事，一任运腾腾。"]},{"t":"辛丑岁暮三首 其二","f":"五言律诗","c":["腊尽无多日，吾生有几年。","老于人事懒，贫觉世情偏。","独枕江湖梦，闭门风雪天。","三杯动诗兴，得句落梅边。"]},{"t":"辛丑岁暮三首 其一","f":"五言律诗","c":["日月易流转，一年仍一年。","身从忧患老，事逐岁时迁。","白首未闻道，清贫不愧天。","寒林松柏瘦，花柳又春妍。"]},{"t":"辛未元日上楼参政攻愧斋先生","f":"七言律诗","c":["东风入仗庆云翔，百辟朝元奉玉皇。","一代安危寄黄发，群生枯瘁转青阳。","梅花结果调勋鼎，柏叶宜年上寿觞。","宰相黑头天子圣，赖公同与措时康。"]},{"t":"邵阳赵节斋史君同黄季玉以合江亭三字分韵","f":"五言律诗","c":["万里清秋景，都归乎此亭。","光阴几今古，天地一宫廷。","澬水东西白，梅山表里青。","登临生酒兴，欲醉又还醒。"]},{"t":"陈伯可山亭","f":"五言律诗","c":["梯险登霞外，乘流过竹西。","寒溪随雨涨，高阁与云齐。","双鹤有时舞，孤猿何处啼。","清吟无尽兴，白石可留题。"]},{"t":"陈孟参陈明子同游麻姑山","f":"七言律诗","c":["麻姑坛上共登临，野客悠然起道心。","丹井汲泉深百尺，星杉耸壑到千寻。","青莲花白仙踪远，乌桕叶红秋意深。","何用金槃擘麟脯，山肴浊酒可同斟。"]},{"t":"陈漕领客西园赏海棠","f":"七言律诗","c":["追随玉节赏仙葩，满座风流客更嘉。","锦绣有光摇竹影，珍珠无价买春华。","猩红滴滴娇含蕊，雪白纷纷老半花。","肯对骚坛轻著语，后山诗句已名家。"]},{"t":"饮中","f":"七言律诗","c":["布衣不换锦宫袍，刺骨清寒气自豪。","腹有别肠能贮酒，天生左手惯持螯。","蝇随骥尾宜千里，鹤在鸡群亦九皋。","贤似屈平因独醒，不禁憔悴赋离骚。"]},{"t":"饮中达观","f":"七言律诗","c":["人生安分即逍遥，莫向明时叹不遭。","赫赫几时还寂寂，闲闲到底胜劳劳。","一心似水惟平好，万事如棋不著高。","王谢功名有遗恨，争如刘阮醉陶陶。"]},{"t":"饮萧和伯家醉登快阁和杨伯子题分明观韵","f":"五言律诗","c":["醉归萧史宅，快阁倚西东。","山敛过云雨，江无起浪风。","月行银汉上，人在玉壶中。","天眼照尘世，应怜鹤发翁。"]},{"t":"事机","f":"五言律诗","c":["天下事机别，朝廷局面新。","台官迁不定，年号改何频。","黜陟由明主，安危仗老臣。","祖宗成宪在，即此是经纶。"]},{"t":"京口别石龟翁际可","f":"七言律诗","c":["把剑樽前砍地歌，有何留恋此蹉跎。","心期难与俗子道，世事不如人意多。","莲叶已空犹有藕，菊花虽老不成莎。","扁舟四海五湖上，何处不堪披钓蓑。"]},{"t":"京口遇薛野鹤","f":"七言律诗","c":["天下江山第一州，可能无地著诗流。","黄金不爱买官职，白发犹堪上酒楼。","懊恨牡丹遭雨厄，叮咛芍药为春留。","狂吟有禁风骚歇，语燕啼鶑代唱酬。"]},{"t":"侄孙子直家有西阁吾有东楼相望秋来景物佳甚","f":"五言律诗","c":["逼仄人间世，思从造物游。","君方倚西阁，吾亦上东楼。","挹彼千峰秀，森然万象秋。","相看成二老，更有几年留。"]},{"t":"侄孙子渊新居落成二首 其二","f":"五言律诗","c":["一区扬子宅，中有读书堂。","早觉儒风好，兼看野趣长。","籓篱带花竹，里巷接农桑。","安得茅三架，为邻住汝傍。"]},{"t":"侄孙子渊新居落成二首 其一","f":"五言律诗","c":["结屋邻苍海，开门面翠屏。","堂前萱草绿，寿母鬓丝青。","礼乐陈樽俎，诗书立户庭。","一时勤卜筑，百世享康宁。"]},{"t":"侄孙亦龙作亭于小山之上□余以野亭名之得诗五首 其五","f":"五言律诗","c":["田间四五月，此景看来稀。","翼翼青苗上，双双白鸟飞。","茅茨林下住，蓑笠雨中归。","拍岸瓜藤水，不须忧岁饥。"]},{"t":"侄孙亦龙作亭于小山之上□余以野亭名之得诗五首 其四","f":"五言律诗","c":["勿谓此亭水，岿然气不群。","静中观变化，闲处立功勋。","水细通岩窦，亭高压海云。","隐居行素志，不负圣明君。"]},{"t":"侄孙亦龙作亭于小山之上□余以野亭名之得诗五首 其三","f":"五言律诗","c":["诗礼家声重，田园活计饶。","自甘为野客，不愿仕王朝。","时为花开眼，谁因米折腰。","此心安出处，何日不逍遥。"]},{"t":"侄孙亦龙作亭于小山之上□余以野亭名之得诗五首 其二","f":"五言律诗","c":["蔡外有馀地，登临作此亭。","心如乔木古，眼共远山清。","社酒谁同醉，村歌自可听。","有时来夜坐，收拾读书萤。"]},{"t":"侄孙亦龙作亭于小山之上□余以野亭名之得诗五首 其一","f":"五言律诗","c":["平地变丘壑，安排若自然。","为山移白石，凿沼贮清泉。","栗里有松竹，兰亭无管弦。","轩裳非我事，在野不妨贤。"]},{"t":"侄孙仲晦亦龙和前诗甚佳其家有林塘之胜兄弟和睦日以奉亲为乐用此韵以美之","f":"五言律诗","c":["有母身长健，无营家自丰。","林塘孝子宅，诗礼古人风。","垄亩秋成后，弟兄和气中。","时闻有佳话，常欲访王戎。"]},{"t":"侄孙炳以东野农歌一编来细读足以起予七言有汲水灌花私雨露临池叠石幻溪山草欺兰瘦能香否杏笑梅残柰俗何似此两联皆自出新意自可传世然言语之工又未足多其体格纯正气象和平为可喜余非谀言自有识者因题其卷末以归之","f":"五言律诗","c":["吾宗有东野，诗律颇留心。","不学晚唐体，曾闻大雅音。","霜空孤鹤唳，云洞老龙吟。","群噪无才思，昏鸦自满林。"]},{"t":"侄孙景文多女贺其得雄","f":"五言律诗","c":["阴极一阳转，君家气数回。","试看庭竹上，新有凤雏来。","端的传书种，分明是福胎。","三朝食牛气，端不类婴孩。"]},{"t":"侄淑远游不得书","f":"五言律诗","c":["客梦江湖远，穷居骨肉离。","尺书无寄处，中夜不眠时。","念尔衣裘薄，满怀风露悲。","狂游断消息，深负竹林期。"]},{"t":"净明","f":"五言律诗","c":["林峦相掩映，岩谷独玲珑。","下置维摩室，上通龙伯宫。","灵珠四时雨，秋水一帘风。","甚欲观新月，山高脚力穷。"]},{"t":"到鄂渚","f":"七言律诗","c":["连宵歌舞醉东楼，不信樽前有别愁。","半夜月明何处笛，长江风送故人舟。","十年浪迹游淮甸，一枕高眠到鄂州。","明日拟苏堤上看，当春杨柳政风流。"]},{"t":"和高与权","f":"七言律诗","c":["相逢休说昧平生，高适能诗久擅名。","欲课荒芜来入社，羞将老丑对倾城。","近来客里仍多病，强向花前举一觥。","乐极自伤头白早，樽前知我孟云卿。"]},{"t":"和韶州许使君令子送别之韵","f":"七言律诗","c":["诗瘦吾非沈隐侯，五穷相值结为雠。","方愁度岭无相识，却喜闻韶到此州。","世道从来三不合，客行何止七宜休。","故人知我平生事，肯笑苏秦著弊裘。"]},{"t":"咏梅投所知","f":"七言律诗","c":["洁白无瑕美不娇，烱如珠玉粲林皋。","独开残腊与时背，奄胜众芳其格高。","欲启月宫休种桂，如何仙苑却栽桃。","不将品质分优劣，痛饮花前读楚骚。"]},{"t":"因风再寄南昌故人兼简王帅子文 其二","f":"五言律诗","c":["江湖归亦好，朋友恨相疏。","倏作三年别，才通一纸书。","诗盟谁是主，世道正愁予。","若见王都督，烦君问起居。"]},{"t":"因风再寄南昌故人兼简王帅子文 其一","f":"五言律诗","c":["寄声黄与宋，书去望书还。","别后交情在，年来世路艰。","吾思蹈东海，君合隐西山。","诗卷勤收拾，留名天地间。"]},{"t":"夜吟呈赵东岩","f":"五言律诗","c":["汲井漱残酒，行吟到夜分。","一轩清似洗，万籁寂无闻。","风送迎秋雨，天收翳月云。","鸡鸣庭户白，人事又纷纷。"]},{"t":"夜宿田家","f":"七言律诗","c":["簦笠相随走路岐，一春不换旧征衣。","雨行山崦黄泥坂，夜扣田家白板扉。","身在乱蛙声里睡，心从化蝶梦中归。","乡书十寄九不达，天北天南雁自飞。"]},{"t":"宜春东湖呈赵使君","f":"五言律诗","c":["东园有佳趣，五马共登临。","介石见古意，月台延赏心。","虽然近城郭，元不远山林。","能使一州润，秀江秋水深。"]},{"t":"岳市胜业寺禹柏","f":"五言律诗","c":["三千年老柏，怪怪复奇奇。","剖彼一枯腹，离为九折枝。","蟠根半生死，阅世几兴衰。","神禹所栽植，山灵常护持。"]},{"t":"庚子荐饥 其四","f":"五言律诗","c":["乘时皆闭粜，有谷贵如金。","寒士糟糠腹，豪民铁石心。","可怜饥欲死，那更病相侵。","到处闻愁叹，伤时泪满襟。"]},{"t":"庚子荐饥 其三","f":"五言律诗","c":["饿走抛家舍，从横死路岐。","有天不雨粟，无地可埋尸。","劫数惨如此，吾曹忍见之。","官司行赈恤，不过是文移。"]},{"t":"庚子荐饥 其一","f":"五言律诗","c":["正月彗星出，连年旱魃兴。","自应多变故，何可望丰登。","孰有回天力，谁怀济世能。","嫠居不恤纬，忧国瘦崚嶒。"]},{"t":"庚子荐饥 其五","f":"五言律诗","c":["杵臼成虚设，蛛丝网釜鬵。","啼饥食草木，啸聚斫山林。","人语无生意，鸟啼空好音。","休言谷价贵，菜亦贵如金。"]},{"t":"庚子荐饥 其二","f":"五言律诗","c":["连岁遭饥馑，民间气索然。","十家九不爨，升米百馀钱。","凛凛饥寒地，萧萧风雪天。","人无告急处，闭户抱愁眠。"]},{"t":"建昌道上","f":"五言律诗","c":["凛凛北风劲，行行西路赊。","人情甘淡薄，世事苦参差。","酒易逢知己，诗难遇作家。","林间数点雪，错认是梅花。"]},{"t":"所闻","f":"五言律诗","c":["北风如许急，亦使客心寒。","近得襄阳报，仍闻蜀道难。","三杯中夜酒，一枕几时安。","江上两都督，何人上将坛。"]},{"t":"所闻","f":"五言律诗","c":["今虏既亡后，中间消息稀。","山河谁是主，豪杰故乘机。","喜报三京复，旋闻二赵归。","此行关大义，天意忍相违。"]},{"t":"所闻二首 其二","f":"五言律诗","c":["右席须贤久，丹书几度催。","贼惊中使转，人望相公来。","问政曲江宅，调羹庾岭梅。","莫因多病后，虚出应三台。"]},{"t":"所闻二首 其一","f":"五言律诗","c":["屡遣和戎使，三边未解兵。","武夫权渐重，□□望何轻。","天下思豪杰，君王用老成。","时无渭滨叟，白首致功名。"]},{"t":"法曹罗立之酒边举数首皆仆故人为我寄声","f":"五言律诗","c":["佳士欣相识，吟边问姓名。","官为三语掾，诗到五言城。","野客可怜我，故人烦寄声。","白头归故隐，秋后会群英。"]},{"t":"罗汉寺","f":"七言律诗","c":["半空紫翠隔微茫，隐隐钟声落下方。","名胜直同天地老，青山不管古今忙。","散分瀑布烟霞润，点检苍松岁月长。","绝顶好云如恋客，尽教怡阅到斜阳。"]},{"t":"贤女祠","f":"五言律诗","c":["士有败风节，惭魂埋九京。","幽闺持大谊，千载著嘉名。","父不重然诺，女能轻死生。","寒潭堕秋月，心迹两清明。"]},{"t":"贤良一和五篇不可及","f":"五言律诗","c":["世路从他险，输君酒盏深。","立谈双白璧，一诺百黄金。","志大不少屈，诗工非苦吟。","相随万里去，老鹤岂无心。"]},{"t":"贫作负恩人为何宏甫作","f":"五言律诗","c":["九陌尘中事，三生石上身。","狂为好诗客，贫作负恩人。","十载江村别，扁舟淦水滨。","音书久不至，得梦往来频。"]},{"t":"郑南夫云林隐居","f":"五言律诗","c":["一来陪胜践，再到惜蹉跎。","记得山中景，行寻竹外坡。","天寒梅信早，海近雁声多。","烟渚蒲洲外，时闻欸乃歌。"]},{"t":"金山","f":"五言律诗","c":["水涌孤峰出，波深日夜闻。","重岩戍铁屋，双塔碍行云。","天地八窗迥，江淮两岸分。","登临多感慨，北雁又成群。"]},{"t":"金陵游览用刘子明韵","f":"七言律诗","c":["英雄割据已焉哉，逝水滔滔去不回。","里巷难寻王谢宅，江山空对凤凰台。","登临无伴诗为侣，兴废不知梅自开。","同是游人不同乐，青楼歌舞待君来。"]},{"t":"钓台","f":"七言律诗","c":["赤符新领旧乾坤，多谢君王问故人。","暂作客星侵帝座，终为渔父老江滨。","层台不啻几千仞，直钓何曾挂一鳞。","莫道羊裘欠图画，丹青难写子陵真。"]},{"t":"雨后有感","f":"五言律诗","c":["逐日愁闻雨，今朝喜遇晴。","云开山献状，月出海生明。","天地有常理，古今无限情。","静中观世变，安得见河清。"]},{"t":"临江小泊","f":"五言律诗","c":["舣舟杨柳下，一笑上茶楼。","适与胡僧遇，非因越女留。","云行山自在，沙合水分流。","独酌临清泚，知心是白鸥。"]},{"t":"临江军新岁呈王幼学监簿","f":"五言律诗","c":["梦说去年事，诗从昨夜吟。","三杯新岁酒，千里故乡心。","人共梅花老，愁连江水深。","家书忽在眼，一纸直千金。"]},{"t":"南丰县南台包敏道赵伯成同游","f":"五言律诗","c":["笑傲南台上，东风吹鬓丝。","眼明花在处，春好雨晴时。","楼阁多临水，溪山可赋诗。","留连无尽意，故遣酒行迟。"]},{"t":"南台寺长老乃福州士人陈其姓语及光拙庵遭际寺乃石头和尚道场","f":"五言律诗","c":["元龙湖海士，参得石头禅。","卓笔翻千偈，住山今十年。","安心一丘壑，过眼几云烟。","莫笑拙庵拙，声名动九天。"]},{"t":"南安王使君领客湛泉流觞曲水","f":"七言律诗","c":["横浦堂前举一卮，古榕阴下坐多时。","连朝好雨千山润，昨夜新秋一叶知。","梅岭乡来逢行者，兰亭今日又羲之。","家声不坠风流在，如见初寮说好诗。"]},{"t":"南剑溪上","f":"五言律诗","c":["长舟不用柂，沙上木为篙。","溪路湾环转，滩声日夜号。","居人不觉险，行客始知劳。","四望无平地，山田级级高。"]},{"t":"南康六老堂","f":"七言律诗","c":["庐山脚下开亭馆，柰此千峰百嶂何。","逸少大书池上墨，少陵狂作醉时歌。","碧荷秋老香犹在，好月夜深明更多。","五老揖君天上笑，把杯相对酌金波。"]},{"t":"南康县用东坡留题韵","f":"七言律诗","c":["镜中双鬓已非鸦，身在江湖心在家。","道路飘零如柳絮，山川迤逦近梅花。","客行有债频沽酒，老怕无眠戒饮茶。","昨夜梦归沧海上，钓竿横插雁边沙。"]},{"t":"南康县刘隐居","f":"五言律诗","c":["秋风送纨扇，终日御瑶琴。","祇可自为乐，不求人赏音。","无心问轩冕，此地即山林。","堪笑红尘客，飘零雪满簪。"]},{"t":"客中岁晚呈何宏甫","f":"五言律诗","c":["岁事费料理，三杯意适然。","与其愁度日，曷若醉忘年。","桑落冬前酒，梅花雪后天。","不知身是客，多谢主人贤。"]},{"t":"客自邵武来言王野使君平寇 其二","f":"五言律诗","c":["太守自监军，片胆大如身。","立马斩数贼，犒军捐万缗。","威行千里外，手活一城民。","孰谓书生怯，书生中有人。"]},{"t":"客自邵武来言王野使君平寇 其一","f":"五言律诗","c":["闻说贼来日，君能判死生。","扁舟载母去，倚剑到天明。","百姓各逃命，四旁无援兵。","王尊岂非勇，独自守孤城。"]},{"t":"客游","f":"七言律诗","c":["不能郁郁窟中藏，大笑出门游四方。","与世周旋持酒盏，观人胜败坐棋坊。","倒餐甘蔗入佳境，昼著锦衣归故乡。","此志十年犹未遂，倚楼心事楚天长。"]},{"t":"客中寄家书并简季道侄","f":"五言律诗","c":["东隐三年别，西风一纸书。","逢人相问讯，念我独勤渠。","游子司吾土，先人有弊庐。","欲归归未得，妻子定何如。"]},{"t":"屏上怀黄伯高兄弟","f":"五言律诗","c":["扁舟到溪上，移杖即行吟。","问麦雨多少，探梅春浅深。","古屏今日景，脩竹旧时阴。","畴昔同游者，遗踪何处寻。"]},{"t":"峡山二首 其二","f":"五言律诗","c":["欲访飞来殿，维舟上峡山。","有溪流屋下，无路入云间。","犀解捐金索，猿能记玉环。","无从旌往事，有地足跻攀。"]},{"t":"峡山二首 其一","f":"五言律诗","c":["山近江如束，林深路欲迷。","平沙印虎迹，绝壁听猿啼。","绿水人谁钓，黄茅地可畦。","幽居堪避世，何必武陵溪。"]},{"t":"度淮","f":"五言律诗","c":["一雨足秋意，孤吟写客怀。","人情容易变，身事苦难谐。","每日思归浙，今朝却度淮。","此生烦造物，略略为安排。"]},{"t":"思归 其二","f":"七言律诗","c":["躬耕海上奈无田，乍可经营买钓船。","未有人供令狐米，欲从鬼借尉迟钱。","回头归路三千里，藉手还乡五百篇。","幸遇太平时节好，白云深处了残年。"]},{"t":"思归 其一","f":"七言律诗","c":["地上皇皇虮虱臣，著衣吃饭亦君恩。","不能待诏金銮殿，尝欲献诗光范门。","身在草茅忧社稷，恨无毫发补乾坤。","才疏命薄成何事，白首归耕东海村。"]},{"t":"思归二首 其二","f":"七言律诗","c":["老矣归欤东海村，长裾不复上王门。","肉糜岂胜鱼羹饭，纨裤何如犊鼻裈。","是处江山如送客，故园桐竹已生孙。","分无功业书青史，或有诗名身后存。"]},{"t":"思归二首 其一","f":"七言律诗","c":["吟诗不换校书郎，但欲封侯管醉乡。","疏懒无成嵇叔夜，清狂似达贺知章。","安贫不怕黄金尽，既老从教白发长。","百计不如归去好，子孙相对说农桑。"]},{"t":"思家","f":"五言律诗","c":["湖海三年客，妻孥四壁居。","饥寒应不免，疾病又何如。","日夜思归切，平生作计疏。","愁来仍酒醒，不忍读家书。"]},{"t":"括苍石门瀑布","f":"七言律诗","c":["少泊石门观瀑布，明知是水却疑非。","乱抛雪玉从天下，散作云烟到地飞。","夜听萧萧洗尘梦，风吹细细湿人衣。","谢公蜡屐经行处，闻有留题在翠微。"]},{"t":"故人陈秘书家有感 其一","f":"五言律诗","c":["晚春风雨后，花絮落无声。","绿泛新荷出，青铺细草生。","私蛙为谁噪，老犬伴人行。","旧日狂宾客，樽前笑不成。"]},{"t":"故人陈秘书家有感 其二","f":"五言律诗","c":["林塘劫火后，更作两家分。","笋拆头抢地，松高气拂云。","老夫来访旧，稚子解谈文。","自是麒麟种，那随雁鹜群。"]},{"t":"春日","f":"五言律诗","c":["淫滞江湖久，蹉跎岁月新。","客愁茅店雨，诗思柳桥春。","秣马寻归路，骑鲸问故人。","山林与朝市，何处著吾身。"]},{"t":"春日二首呈黄子迈大卿 其一","f":"七言律诗","c":["野人何得以诗鸣，落魄骑驴走帝京。","白发半头惊岁月，虚名一日动公卿。","颇思湖上春风约，不柰楼头夜雨声。","柳外断云筛日影，试听幽鸟话新晴。"]},{"t":"春日二首呈黄子迈大卿 其二","f":"七言律诗","c":["帝里风光二月新，西湖几队踏青人。","杏花时节偏饶雨，杨柳门墙易得春。","或是或非尘里事，无穷无达醉中身。","五陵年少誇豪举，寂寞诗家戴叔伦。"]},{"t":"春日风雨中","f":"七言律诗","c":["潇潇风雨闭柴门，年纪衰颓病著身。","大似梁鸿居海曲，略如公干卧漳滨。","三春晴暖无多日，一世安闲有几人。","闻道明朝新酝熟，不妨祭灶请比邻。"]},{"t":"春日怀家","f":"五言律诗","c":["细数平生事，何堪挂齿牙。","客游儿废学，身拙妇持家。","开瓮尝春酒，租山摘早茶。","关心此时节，归兴满天涯。"]},{"t":"春尽日","f":"五言律诗","c":["撚指过三月，又当春夏交。","花残蜂课蜜，林茂鸟安巢。","芳草生青霭，新篁展绿稍。","风骚将断绝，谁有续弦胶。"]},{"t":"昭武刘圻甫以㟳篁隐居图求诗","f":"五言律诗","c":["相对两山碧，春风摇绿篁。","一巢云建造，三涧水宫商。","谷口躬耕稼，盘中歌寿昌。","桃花认行路，他日访刘郎。"]},{"t":"泉州紫极宫寿星殿古桧诸葛机宜同赋","f":"七言律诗","c":["浪说陈朝八桧碑，何如此桧古而奇。","灵根据地高千尺，黛色浮空阅四时。","入欲栋梁劳想像，树存陵谷有迁移。","寿星赐汝长生诀，化作苍龙守殿墀。"]},{"t":"泉南","f":"五言律诗","c":["南地无冰雪，常疑暖作灾。","昼昏山雾合，寒变海风来。","垄麦衔芒早，梅花带叶开。","客中归未得，岁事渐相催。"]},{"t":"洞霄宫","f":"七言律诗","c":["天柱峰头一振衣，云开岩路雨晴时。","登临欲访神仙事，纪述都无汉晋碑。","拍手数声龙井跃，篝灯一览洞天奇。","林间安得栖身处，欲炼金丹饵玉芝。"]},{"t":"洪子中大卿同登远碧楼归来有诗","f":"五言律诗","c":["角巾华屋下，丘壑在其旁。","寄兴青山远，忧时白发长。","无心当世用，袖手看人忙。","善自为身计，须传活国方。"]},{"t":"癸巳端午呈李伯高","f":"七言律诗","c":["客里几逢端午节，看成雪鬓与霜髯。","救人采得三年艾，背世翻成六日蟾。","老境可怜归未得，羁怀长是病相兼。","猛思一醉酬风月，笑撚菖花揭酒帘。"]},{"t":"癸卯岁旦","f":"五言律诗","c":["淳祐第三载，正朝把一杯。","老夫真是病，贺客不须来。","择日脩茅屋，当春觅柳栽。","新年莫多事，且放好怀开。"]},{"t":"秋日","f":"五言律诗","c":["秋风梧叶雨，衮衮送秋凉。","一气四时转，几人双鬓苍。","旧游如说梦，久客乍还乡。","欲作安居计，生涯尚渺茫。"]},{"t":"秋日早行","f":"五言律诗","c":["雁叫秋容老，乌飞曙色分。","晨炊何草草，宿酒尚醺醺。","野旷连沧海，山长带白云。","马行沙上路，惊起白鸥群。"]},{"t":"秋日病馀","f":"七言律诗","c":["桂子吹香风露深，老夫吟了听蝉吟。","秋来剩有行山兴，病后全无涉世心。","诗苦积成双白发，酒豪轻用万黄金。","平生意气今如许，独抱传家一破琴。"]},{"t":"秋兴有感","f":"五言律诗","c":["客游江海上，几度见秋风。","远浦芦花白，疏林秋实红。","人情朝暮变，景物古今同。","老眼犹明在，从教两耳聋。"]},{"t":"秋怀","f":"五言律诗","c":["红叶无人扫，黄花独自妍。","听谈天下事，愁到酒樽前。","水阔终非海，楼高不到天。","昔人已怀古，况复后千年。"]},{"t":"秋夜旅中","f":"五言律诗","c":["旅食思乡味，砧声起客愁。","夜凉风动竹，人静月当楼。","浮世百年梦，他乡几度秋。","店翁新酒熟，一醉更何求。"]},{"t":"胡倅送羊烹以会客","f":"五言律诗","c":["烹膻会宾客，花酒一时来。","愁逐歌声散，心随笑口开。","饮疑金盏漏，醉到玉山颓。","借问欢娱地，相逢能几回。"]},{"t":"舣棹清江","f":"七言律诗","c":["舣棹江滨访旧游，十年重到戏渔洲。","不知芳树在何许，但见落花从此流。","我醉欲眠因假榻，客行未定且登楼。","有钱剩买张家酒，准备明朝话别愁。"]},{"t":"觉慈寺","f":"七言律诗","c":["踏破白云登上方，自嫌尘土涴禅床。","千山月色令人醉，半夜梅花入梦香。","深谷不妨春到早，老僧殊为客来忙。","山童懒惯劳呼唤，自拗枯松煮朮汤。"]},{"t":"赵升卿有官不肯为里居有贤声访之于深巷中","f":"七言律诗","c":["深居陋巷不妨幽，翠竹当门水满沟。","每遇事来先觉懒，欲为官去又还休。","田园自乐陶元亮，乡里多称马少游。","除却读书无所好，有时闲作北岩游。"]},{"t":"赵用甫提举梦中得片云不隔梅花月之句时被命入朝雪中送别用其一句补以成章","f":"七言律诗","c":["一时议论动诸公，有诏西来玉节东。","又见清朝更大化，好趋丹陛奏孤忠。","片云不隔梅花月，一雪翻成柳絮风。","把酒莫辞今夕醉，明朝车马去匆匆。"]},{"t":"赵丞话旧","f":"五言律诗","c":["忆作齐安别，相逢直到今。","寒温片时话，故旧百年心。","折柳送行客，栽松遇赏音。","尊前强歌笑，两鬓雪霜深。"]},{"t":"赵克勤曾橐卿景寿同登黄南恩南楼 其一","f":"七言律诗","c":["欲从高处赏新秋，上尽层坡更上楼。","天地无穷吾辈老，江山有恨古人休。","宁随狡兔营三窟，且跨飞鸿阅九州。","忆著当年杜陵老，一生飘泊也风流。"]},{"t":"赵克勤曾橐卿景寿同登黄南恩南楼 其二","f":"七言律诗","c":["鄂州南楼不可到，到此南楼眼亦青。","乾坤日月与高致，城郭江山无遁形。","把酒纵谈心耿耿，倚栏遐眺鬓星星。","世间万事关愁思，莫使秋风吹酒醒。"]},{"t":"赵叔垕山堂安下其家适有丧事","f":"五言律诗","c":["一径沿溪入，数椽松竹间。","岂知人事变，自觉客身闲。","采菊出寻酒，移床卧看山。","苍头无可作，把钓过西湾。"]},{"t":"赵敬贤送荔枝","f":"五言律诗","c":["荔子固多种，色香俱不同。","新来尝小绿，又胜擘轻红。","大嚼思千树，分甘仅一笼。","尝观蔡公谱，梦想到莆中。"]},{"t":"赵端行杜子野游虎丘有诗仆因思旧与赵子野同宿唱和留题","f":"五言律诗","c":["出城十里许，有此一山门。","丘在虎无迹，池清剑有痕。","孤松冠岩顶，万竹绕云根。","借问东轩壁，旧题存不存。"]},{"t":"送王仲彝制机宰浏阳 其一","f":"五言律诗","c":["一身供世用，六月赴官忙。","当此炎天热，知君心地凉。","吏能师卓鲁，县界接潇湘。","试饮浏阳水，清清滋味长。"]},{"t":"送王仲彝制机宰浏阳 其二","f":"五言律诗","c":["浏阳谁谓小，桑柘万家春。","远宦逢知己，推心在惠民。","速宜还县债，闻早缀朝绅。","说与诸公道，方岩后有人。"]},{"t":"送包使君入朝除左曹郎二首 其二","f":"五言律诗","c":["金门行入奏，何以告君王。","请下求贤诏，兼陈活国方。","解纷□□□，救弊细思量。","若见高常簿，言予病在床。"]},{"t":"送包使君入朝除左曹郎二首 其一","f":"五言律诗","c":["宏斋儒者政，赏罚自宜民。","世欲无公论，天知有正人。","侧身观宇宙，平步履星辰。","试把安危事，从头问化钧。"]},{"t":"送刘镇叔安入京谪居三山二十馀年，真西山奏令自便，赵用父使君为唱饯其行，坐客二十八人分韵赋诗，得君字","f":"七言律诗","c":["二十馀年谪宦身，此行便可上青云。","西山一手为推毂，南浦几人争送君。","横水流传无垢集，海神惊见老坡文。","回头莫有关情处，别酒须教满十分。"]},{"t":"送别朱兼佥","f":"七言律诗","c":["恰喜相逢又语离，愁于江上送君时。","清谈未了风吹断，白发可怜天不知。","樗木自肥伤竹瘦，海棠偷放笑梅迟。","黄堂若问痴顽老，新有登楼二十诗。"]},{"t":"送陈幼度运干 其一","f":"五言律诗","c":["台幕三年最，云霄万里程。","西山饯行色，南浦棹新晴。","骨秀荆山璞，胸涵元气英。","更携扛鼎笔，祇合上蓬瀛。"]},{"t":"送陈幼度运干 其二","f":"五言律诗","c":["君是青云料，吾当白发年。","驽骀傍骐骥，鱼鸟各天渊。","他日难忘处，寒宵不忍眠。","挑灯雪窗下，共读雁奴篇。"]},{"t":"送季明府赴太平倅 其一","f":"五言律诗","c":["黄岩号难治，能者治何难。","桃李民心悦，风霜吏胆寒。","公行无不可，私请莫相干。","三尺儿童辈，皆知好长官。"]},{"t":"送季明府赴太平倅 其三","f":"五言律诗","c":["庭闱定省外，都是坐厅时。","尽日身无倦，对天心不欺。","县花潘岳赋，池草惠连诗。","磨取九峰石，刊成德政碑。"]},{"t":"送季明府赴太平倅 其四","f":"五言律诗","c":["通守太平州，金陵在上头。","风寒当一面，江□□千艘。","此日要人物，九天宽顾忧。","诗书用处别，澼絖换封侯。"]},{"t":"送季明府赴太平倅 其二","f":"五言律诗","c":["人说陈胡蔡，合君为四贤。","一廉官似水，三载吏无权。","政自诗书出，民从教化迁。","神明判事笔，一出万人传。"]},{"t":"送赵安仁之官上虞二首 其二","f":"五言律诗","c":["远庵家学在，持此去为官。","冰雪吾身白，风霜吏胆寒。","一心毋妄用，百姓自相安。","贤者妙为政，谁言宰剧难。"]},{"t":"送赵安仁之官上虞二首 其一","f":"五言律诗","c":["表表魁梧相，面如田字方。","早宜朝玉陛，犹自绾铜章。","上挹叶丞相，近瞻商侍郎。","风流接前辈，偃室有辉光。"]},{"t":"送晓山夏肯甫入京","f":"五言律诗","c":["岁月频看镜，功名一据鞍。","勿言行路恶，有志恋家难。","芳草客程远，落花春夜寒。","江湖旧时梦，相逐到长安。"]},{"t":"送黄教授日岩之官章贡","f":"七言律诗","c":["久矣闻名不相识，江湖还有见君时。","出人意表发高论，入我眼中多好诗。","欲对春风开笑口，不堪世事上愁眉。","凭谁寄语谢安石，莫为苍生起太迟。"]},{"t":"送彭司户之官三山","f":"五言律诗","c":["祭酒家风重，民曹官职卑。","公勤为己任，清白取人知。","腊月三山雪，梅花一路诗。","旧时来往处，今有梦相随。"]},{"t":"送湘漕赵蹈中寺丞移宪江东","f":"五言律诗","c":["持节复持节，因循霜鬓侵。","盛衰关大数，豪杰负初心。","宇宙虚长算，江湖寄短吟。","番阳秋水阔，湘浦未为深。"]},{"t":"送蒙斋兄长游天台二首 其二","f":"七言律诗","c":["山林胜处说天台，仙佛多从此地栖。","司马八篇通道妙，丰干一语指人迷。","时逢好酒从容饮，莫把新诗取次题。","白日看云思我否，惠连无分共攀跻。"]},{"t":"送蒙斋兄长游天台二首 其一","f":"七言律诗","c":["方丈蓬莱去渺茫，天台祇在白云傍。","羽衣金策群仙过，珠阁琼楼八桂香。","采药有时逢道侣，挑包遇夜宿僧房。","寒山拾得如相见，指点人间笑几场。"]},{"t":"送滕审言归长沙别无聊","f":"七言律诗","c":["折柳亭前送故人，平沙留得马蹄痕。","云生渡北迷行路，烟起江南认别村。","恨不与君同上道，归来无伴自开樽。","西楼独倚黄昏月，欲倩飞鸿寄断魂。"]},{"t":"送黎明府 其二","f":"五言律诗","c":["县债三年了，乡心万里飞。","一身如许瘦，百姓不妨肥。","买宅凭谁办，抱琴何处归。","诸公竞推毂，稳去著朝衣。"]},{"t":"郡圃寒食","f":"七言律诗","c":["与民同乐一开园，佳节何曾禁得烟。","拍岸绿波浮舴艋，翻空红袖打鞦韆。","眼看花柳心如醉，身在蓬瀛我亦仙。","明日徐翁坟上约，欲求竹帚恐无缘。"]},{"t":"重阳舟中","f":"五言律诗","c":["扁舟何寂寞，绝不见人家。","无处沽村酒，何从问菊花。","溪山澹相对，节序谩云嘉。","牢裹乌纱帽，西风日又斜。"]},{"t":"钟春伯园林","f":"七言律诗","c":["西风吹起莼鲈兴，八座归来有此山。","林麓两峰亭榭外，潇湘一片水云间。","天生景物四时好，人满乾坤几个闲。","语唤石屏非浪语，常思蜡屐共跻攀。"]},{"t":"闻边事","f":"五言律诗","c":["昨日闻边报，持杯不忍斟。","壮怀看宝剑，孤愤裂寒衾。","风雨愁人夜，草茅忧国心。","因思古豪杰，韩信在淮阴。"]},{"t":"闻机上妇说蚕事之辛勤织未成缣往往取偿债家","f":"七言律诗","c":["荷君问讯蚕家事，此是妇人辛苦媒。","典尽衣裳酬叶价，忙无心绪向妆台。","缲声未断机声续，私债未偿官债催。","织未成缣分剪尽，妾身争得一丝来。"]},{"t":"闻严坦叔入朝再用前韵 其一","f":"五言律诗","c":["凄凉风雨日，强把瓮头春。","独守空虚室，那逢耗磨辰。","诗家青眼旧，世路白头新。","每诵梅花句，一心思故人。"]},{"t":"闻严坦叔入朝再用前韵 其二","f":"五言律诗","c":["我本江湖客，归来二月春。","居多闭门日，未卜赏花辰。","绕树鹊声喜，隔帘鶑语新。","可怜垂白叟，却羡踏青人。"]},{"t":"闻时事","f":"五言律诗","c":["雁岂关兵气，鱼常被火灾。","御军先择将，立国可无财。","济世须人物，忠言是福媒。","西山今已往，更待鹤山来。"]},{"t":"闻时事","f":"七言律诗","c":["昨报西师奏凯还，近闻北顾一时宽。","淮西勋业归裴度，江右声名属谢安。","夜雨忽晴看月好，春风渐老惜花残。","事关气数君知否，麦到秋时天又寒。"]},{"t":"闻李将军至建康","f":"五言律诗","c":["匹马径趋府，将军意气多。","来依汉日月，思复晋山河。","边将惭尸素，朝臣奏凯歌。","分明御徂诈，得失竟如何。"]},{"t":"闻杜仪甫出台","f":"五言律诗","c":["台官关系重，用舍一何轻。","诸老多惭德，斯人有直声。","傥来视轩冕，归去即功名。","莫拜宽堂墓，伤心隔死生。"]},{"t":"除夜","f":"七言律诗","c":["扫除茅舍涤尘嚣，一炷清香拜九霄。","万物迎春送残腊，一年结局在今宵。","生盆火烈轰鸣竹，守岁筵开听颂椒。","野客预知农事好，三冬瑞雪未全消。"]},{"t":"倚楼","f":"五言律诗","c":["贤愚不同道，用舍要知机。","涉世有臧否，倚楼无是非。","鸦分枯树立，雁逐断云飞。","朝暮寻常事，何须叹落晖。"]},{"t":"借韵书怀","f":"五言律诗","c":["虚气撑枯腹，长身到老贫。","高吟常骇俗，烂醉若骄人。","京洛繁华梦，江湖浩荡春。","布衣如雪白，不受庾公尘。"]},{"t":"哭赵紫芝","f":"五言律诗","c":["呜呼赵紫芝，其命止于斯。","东晋时人物，晚唐家数诗。","瘦因吟思苦，穷为宦情痴。","忆在藏春圃，花边细话时。"]},{"t":"夏日从子渊侄借茉莉一盆","f":"五言律诗","c":["举眼惊如许，衰怀强自安。","爱凉临水坐，遣病借花看。","物物同天地，人人各肺肝。","从来泾与渭，混作一流难。"]},{"t":"夏日雨后登楼","f":"五言律诗","c":["夏日不苦热，病躯能少康。","数峰楼上景，六月雨馀凉。","今古两虚器，乾坤百戏场。","人生如寄尔，聊以醉为乡。"]},{"t":"夏日续题","f":"五言律诗","c":["海近朝曦赫，山明宿雾消。","紫云萦碧落，白鹭点青苗。","避暑轩亭爽，凭虚眼界遥。","时来一登眺，初不待招邀。"]},{"t":"家中作","f":"七言律诗","c":["四海飘零似落花，十年秋鬓带霜华。","归无驷马空题柱，敝尽貂裘忙到家。","触目半成愁境界，安心旋办老生涯。","可怜持蟹持杯手，小圃携锄学种瓜。"]},{"t":"家居复有江湖之兴","f":"七言律诗","c":["寒儒家舍只寻常，破纸窗边折竹床。","接物罕逢人可语，寻春多被雨相妨。","庭垂竹叶因思酒，室有兰花不炷香。","到底闭门非我事，白鸥心性五湖傍。"]},{"t":"挽大溪姚祥叔即南","f":"五言律诗","c":["庆门今独盛，旧族有光华。","日坐不欺室，天兴积善家。","山林娱晚境，书史是生涯。","手种堂前桂，君看身后花。"]},{"t":"挽立斋杜丞相","f":"五言律诗","c":["邪正不两立，国家当再兴。","有时须有命，称德不称能。","方喜千年遇，如何一旦薨。","世间无哭处，吾欲哭昭陵。"]},{"t":"挽沙溪项公苔湖居士 其二","f":"五言律诗","c":["一曲苔湖上，深居万竹间。","自寻三径乐，早得一身闲。","㶁㶁循除水，林林夹屋山。","伤心白云际，遗迹尚班班。"]},{"t":"挽沙溪项公苔湖居士 其一","f":"五言律诗","c":["读书不成事，何恨老山林。","处世有容德，与人无诤心。","友于兄弟乐，惠彼里闾深。","细把丰碑读，怀贤泪满襟。"]},{"t":"挽赵县丞","f":"五言律诗","c":["雅志思行古，幽居不爱官。","倾家为义举，竭力奉亲欢。","阅世开天镜，藏身作瓦棺。","闻知捐馆日，有梦跨金鞍。"]},{"t":"挽赵县尉","f":"五言律诗","c":["十竹相依住，一官真漫为。","狂来裂轩冕，穷不顾妻儿。","疾世吟孤愤，伤时赋五噫。","高名应不朽，自作墓中碑。"]},{"t":"挽唐吉林咏道","f":"五言律诗","c":["博雅林夫子，隐居城市中。","家贫书甚富，学苦字尤工。","四海交名胜，诸文辨异同。","阿戎谈更好，端不负家风。"]},{"t":"挽温岭丁竹坡","f":"五言律诗","c":["潇洒复潇洒，是为丁竹坡。","生涯浑草草，诗句自多多。","恨不识是叟，悲哉作此歌。","数编遗稿在，不共葬烟萝。"]},{"t":"海上鱼西寺","f":"七言律诗","c":["北风三日弭行舟，登陆因为岛寺游。","自笑奔驰如野马，本无拘束似沙鸥。","人谁与语自缄口，山有可观频举头。","小雨疏烟晚来景，老僧相对倚钟楼。"]},{"t":"海月星天之观","f":"七言律诗","c":["巍然华屋似凌歊，下际沧溟上九霄。","万顷波涛浴蟾兔，一天星斗转魁杓。","征鸿有感人飘泊，宿鹤无声夜寂寥。","谁似风流杨叔子，登临□□□□□。"]},{"t":"海陵光孝长老骥无称山谷后也共谈时事且说黄岩柑橘之美","f":"五言律诗","c":["俗子避形影，僧家共往还。","高谈犯时忌，妙语发天悭。","霜后思新橘，梦中归故山。","何时免奔走，终老白云关。"]},{"t":"涂中见人家卖酒","f":"五言律诗","c":["连岁遭饥馑，人无籴米钱。","今秋好行路，到处说丰年。","村酒新篘浊，溪鱼出网鲜。","黄花留客醉，况近竹林边。"]},{"t":"真州上官漕劝农","f":"五言律诗","c":["小队出行春，旌旗带野云。","草成平寇檄，翻作劝农文。","幕府多奇士，诗书策异勋。","请将边上事，一一奏明君。"]},{"t":"真西山帅长沙祷雨 其二","f":"五言律诗","c":["出郭问农事，家家笑语声。","有田皆足水，既雨亦宜晴。","山下溪流急，街头米价平。","明朝闻领客，相见贺秋成。"]},{"t":"真西山帅长沙祷雨 其一","f":"五言律诗","c":["太守持斋戒，精诚动九天。","骄阳变霖雨，凶岁转丰年。","信是经纶手，行司造化权。","唐时相房杜，斗米直三钱。"]},{"t":"聂侍郎领客观园林之胜饮中出示名贤书画","f":"七言律诗","c":["烈士家风从橐尊，时容野客上朱门。","如登东观图书府，又似西岩水竹村。","自以一闲销日月，谁知万虑满乾坤。","诸公衮衮成何事，不若花前对酒樽。"]},{"t":"莆中遇方□□邀出城买蛎而饮一僧同行","f":"五言律诗","c":["出郭断虹雨，倚楼新雁天。","三杯古榕下，一笑菊花前。","入市子鱼贵，堆盘牡蛎鲜。","山僧惯蔬食，清坐莫流涎。"]},{"t":"袁州化成岩李卫公谪居之地","f":"七言律诗","c":["一岩端坐挹千峰，三两亭台胜概中。","江水骤生连夜雨，松声吹下半天风。","因思世故吾头白，独步林皋夕照红。","欲吐草茅忧国志，谁能唤起赞皇公。"]},{"t":"诸侄孙登白峰观海上一景","f":"五言律诗","c":["自有此山在，无人作此游。","气吞云海浪，笑撼玉峰秋。","开辟几百载，登临第一筹。","诸郎莫高兴，刻石记风流。"]},{"t":"诸诗人会于吴门翁际可通判席上高菊涧有诗仆有客星聚吴会诗派落松江之句方子万使君喜之遂足成篇","f":"五言律诗","c":["客星聚吴会，诗派落松江。","老眼洞千古，旷怀开八窗。","风流谈夺席，歌笑酒盈缸。","杨陆不再作，何人可受降。"]},{"t":"诸葛仁叟县丞极贫能保风节有权贵招之不屑其行","f":"七言律诗","c":["时人谁识老聋丞，满口常谈杜少陵。","俗辈众多吾辈少，素交零落利交兴。","权门炙手炎如火，诗社投身冷似冰。","堪笑皇天无老眼，相知赖有竹林僧。"]},{"t":"读三学士人论事三书 其二","f":"五言律诗","c":["黄屋见闻远，朱门富贵忙。","屠沽思报国，樵牧解谈王。","能转祸为福，毋令圣作狂。","草茅垂白叟，尚拟见时康。"]},{"t":"读三学士人论事三书 其一","f":"五言律诗","c":["邦计伤虚耗，边民苦乱离。","诸公事缄默，三学论安危。","灾异天垂戒，脩为国可医。","传闻上元夜，绝似太平时。"]},{"t":"读王幼学上殿劄子","f":"七言律诗","c":["才到朝廷被论归，孤忠幸有九重知。","神医能识未苏病，国手难翻已败棋。","四海争传治安策，诸公如在太平时。","老夫怀抱缘何事，未到秋来早自悲。"]},{"t":"读严粲诗风撼潇湘覆江空雪月明以其一联隐括为对","f":"五言律诗","c":["笔端有神助，句法自天成。","风撼潇湘覆，江空雪月明。","苦吟非草草，妙趣若平平。","李杜诗坛上，为君题姓名。"]},{"t":"读改元诏口号 其三","f":"五言律诗","c":["国以人为重，人惟德可招。","九重方厉政，诸老尽归朝。","盛事追三代，清风动百僚。","切闻天上语，欢喜到渔樵。"]},{"t":"读改元诏口号 其二","f":"五言律诗","c":["喜见新除目，焚香洗眼看。","老儒居翰苑，正士作台官。","有道为时用，非才处位难。","寄声崔与李，催促到长安。"]},{"t":"读改元诏口号 其一","f":"五言律诗","c":["伏读改元诏，仍观拜相麻。","竞传新政事，方见好官家。","雪作丰年瑞，梅开近腊花。","路逢江上客，立马问京华。"]},{"t":"读放翁先生剑南诗草","f":"七言律诗","c":["茶山衣钵放翁诗，南渡百年无此奇。","入妙文章本平澹，等闲言语变瑰琦。","三春花柳天裁剪，历代兴衰世转移。","李杜陈黄题不尽，先生模写一无遗。"]},{"t":"郭外翁","f":"五言律诗","c":["郭外生涯少，城中籴米归。","种花无处卖，挑菜入篮稀。","风撼倾欹屋，寒生蓝缕衣。","此翁何所乐，谈笑傲轻肥。"]},{"t":"郭伯秀约联骑春游不去有诗","f":"五言律诗","c":["心老寻春懒，年衰跨马难。","便能相强去，未必有真欢。","独酌三杯妙，高眠一枕安。","好花如可折，觅取数枝看。"]},{"t":"都下书怀","f":"七言律诗","c":["京华作梦十年馀，不道南山有弊庐。","白发生来美人笑，黄金散尽故交疏。","明知弄巧翻成拙，除却谋归总是虚。","出处古人都说尽，功名未必胜鲈鱼。"]},{"t":"都下书怀","f":"五言律诗","c":["半月不把镜，羞看两鬓尘。","读书增意气，携刺减精神。","道路谁推毂，江湖赋采蘋。","从来麋鹿性，那作帝乡人。"]},{"t":"都中书怀二首 其二","f":"五言律诗","c":["雪化晴檐雨，炉烘冻壁春。","穷犹恋诗酒，懒不正衣巾。","寂寞安吾分，奔驰失我真。","枯桐就煨烬，容有赏音人。"]},{"t":"都中书怀二首 其一","f":"五言律诗","c":["醉卧长安市，思归东海涯。","瓶馀残腊酒，梅老隔年花。","日与愁为地，时凭梦到家。","乡书三两纸，一读一咨嗟。"]},{"t":"都中次韵申季山","f":"七言律诗","c":["车马喧临十二门，乐从闲处度朝昏。","诗书岂为功名重，轩冕何如道谊尊。","志士不能行所学，明君亦或讳忠言。","世间事事如人意，未必商山有绮园。"]},{"t":"都中怀竹隐徐渊子直院","f":"七言律诗","c":["手携漫刺访朝官，争似沧洲把钓竿。","万事看从今日别，九原叫起古人难。","菊花到死犹堪惜，秋叶虽红不耐观。","多谢天公怜客意，霜风未忍放深寒。"]},{"t":"阅世 其一","f":"七言律诗","c":["一懒一愚兼一痴，从教智士巧能为。","坦途失脚溪山险，暗室萌心天地知。","江水长流无尽意，夕阳虽好不多时。","老夫阅遍人间事，欲和寒山拾得诗。"]},{"t":"阅世 其二","f":"七言律诗","c":["积镪多金生怨尤，一温饱外更何求。","自甘韬遁陶元亮，不爱赢馀马少游。","何取累累兼若若，终成莫莫与休休。","花前适意三杯酒，万事忘机对白鸥。"]},{"t":"阅四家诗卷","f":"七言律诗","c":["阅尽四家诗卷子，自然优劣在其中。","石龟野鹤心相合，菊涧花翁道不同。","鸣凤翱翔上霄汉，乱蝉萧瑟度秋风。","一篇论尽诸家体，忆著当年巩睡翁。"]},{"t":"阅旧稿见乔丞相诗跋因成此诗","f":"七言律诗","c":["三十年前旧诗册，两行钧翰俨如新。","自甘白屋为寒士，敢说黄扉有故人。","五雨十风勤燮理，九州四海费经纶。","年踰八十貂蝉贵，不负明君恐负身。"]},{"t":"陪虞使君登岳阳楼","f":"七言律诗","c":["片帆飞过洞庭来，百尺巍巍水面开。","疑泛灵槎上河汉，如从弱水到蓬莱。","钧天广乐无闻矣，袖剑仙人安在哉。","物物尽随波浪去，君山一点独崔嵬。"]},{"t":"偶见飞蝶追思旧游录之","f":"五言律诗","c":["早被春情误，浑身著粉衣。","最宜花上见，解向梦中飞。","蜂媵为游伴，蛛丝设祸机。","滕王小图画，一一造精微。"]},{"t":"宿农家","f":"五言律诗","c":["宿此屋头阁，瓦窗通月明。","夜深鸲鹆噪，人静桔槔声。","村落有古意，田园关客情。","儒衣成底事，所得是虚名。"]},{"t":"宿农家","f":"五言律诗","c":["门巷规模古，田园气味长。","小桃红破萼，大麦绿衔芒。","稚犬迎来客，归牛带夕阳。","儒衣愧飘泊，相就说农桑。"]},{"t":"寄山台赵庶可二首 其二","f":"五言律诗","c":["顷上山台谒，临行辱赠诗。","相思寸心在，莫讶尺书迟。","好月登楼夜，清秋落木时。","见君花萼集，梦到谢公池。"]},{"t":"寄山台赵庶可二首 其一","f":"五言律诗","c":["天族文章士，会稽山水州。","地灵钟秀异，人物信风流。","要自用卿法，如何与妇谋。","功名须早计，莫为海云留。"]},{"t":"寄广西漕陈鲁叟诰院","f":"七言律诗","c":["回首元龙百尺楼，一时诗酒记同游。","好山历历在人眼，流水滔滔任客舟。","归雁欲从何处去，落花恨不为春留。","锦囊佳句无人问，自别君来白尽头。"]},{"t":"寄永嘉太守赵茂实 其二","f":"五言律诗","c":["身为吟诗瘦，家因好谊贫。","如何贤太守，不念可怜人。","橘井谁知处，桃源莫问津。","秋风吹白发，沧海老垂纶。"]},{"t":"寄永嘉太守赵茂实 其一","f":"五言律诗","c":["龚黄古贤牧，政事见于今。","疾恶风霜手，活人天地心。","躬行循吏传，时作谢池吟。","我欲依刘表，常忧老病侵。"]},{"t":"寄节斋陈叔方寺丞","f":"五言律诗","c":["今时古君子，玉立众人间。","再世黄叔度，三生元鲁山。","把麾浑细事，忧国欲愁颜。","恨不频相见，空书谩往还。"]},{"t":"寄寻梅","f":"七言律诗","c":["寄声说与寻梅者，不在山边即水涯。","又恐好枝为雪压，或生幽处被云遮。","蜂黄涂额半含蕊，鹤膝翘空疏带花。","此是寻梅端的处，折来须付与诗家。"]},{"t":"寄朱仲是兼佥","f":"七言律诗","c":["光阴日夜催吾老，已作鸡皮鹤发翁。","万事装成百年梦，五行注定一生穷。","残花但有凋零分，枯木难沾造化功。","若见黄堂烦寄语，何如停我雪楼中。"]},{"t":"寄耒阳令严坦叔","f":"五言律诗","c":["士元堂上坐，千载仰清规。","百里宜民政，数篇怀古诗。","江连杜甫墓，水落蔡伦池。","公暇登临处，宁无忆我时。"]},{"t":"寄吴明辅秘丞 其一","f":"七言律诗","c":["吾乡幸有吴夫子，星斗网罗文字胸。","百鸟收声听鸣凤，千山落木秀孤松。","旁通沧海江山水，高压云城帢帻峰。","每见一斑三叹息，白头未得奉从容。"]},{"t":"寄吴明辅秘丞 其二","f":"七言律诗","c":["七十七翁犹眼明，三台星畔见奎星。","文章有气吞馀子，议论无差本六经。","愧我不能攀逸驾，得君自足振颓龄。","玉溪常与荆溪接，分得馀波到石屏。"]},{"t":"寄抚州楼使君","f":"七言律诗","c":["梦上江西江上船，行随五马五峰前。","临川太守贤无敌，攻愧先生学有传。","佳政可书循吏传，斯民共乐太平年。","不知拟岘台前景，公暇清吟得几篇。"]},{"t":"寄沈庄可","f":"五言律诗","c":["无山可种菊，强号菊山人。","结得诸公好，吟成五字新。","红尘时在路，白发未离贫。","吾辈浑如此，天公似不仁。"]},{"t":"寄建康留守制使赵用父都丞侍郎 其一","f":"五言律诗","c":["蛮貊闻名姓，当今有此人。","片心天共广，一笑物为春。","花满金陵路，风清玉塞尘。","九重方简注，四海望经纶。"]},{"t":"寄建康留守制使赵用父都丞侍郎 其二","f":"五言律诗","c":["燕许文章笔，片言轻万金。","先人十诗序，孝子一生心。","入手方为宝，三年等到今。","九泉应有望，取璧照山林。"]},{"t":"寄郑润甫提干","f":"五言律诗","c":["吾乡有佳士，官小患才多。","文可登词苑，直宜居谏坡。","春风能活物，砥柱不随波。","客里喜相遇，飘零柰我何。"]},{"t":"寄南昌故人黄存之宋谦甫二首 其二","f":"五言律诗","c":["久客归来后，家如旧日贫。","青山何处隐，白发也愁人。","畎亩一生事，乾坤百病身。","时无嵇吕驾，相忆莫相亲。"]},{"t":"寄南昌故人黄存之宋谦甫二首 其一","f":"五言律诗","c":["谦甫多才思，存之重谊襟。","一书愁话别，千里梦相寻。","南浦扁舟上，东湖万柳阴。","旧时行乐处，何事不关心。"]},{"t":"寄复斋陈寺丞二首 其二","f":"七言律诗","c":["长忆西湾系小舟，野人曾伴使君游。","夜浮星子邀明月，雨对庐君说好秋。","坐拥红妆磨宝砚，醉歌赤壁写银钩。","当时一段风流事，翻作相思一段愁。"]},{"t":"寄复斋陈寺丞二首 其一","f":"七言律诗","c":["岂说从来用处难，出乘五马看庐山。","凤凰览德下千仞，虎豹憎人上九关。","持论太高天动色，忧时未老鬓先斑。","平生风节谁其似，汲黯朱云伯仲间。"]},{"t":"寄姚楚州 其一","f":"五言律诗","c":["人材当世用，缓急敢辞难。","身挟天威重，名惊贼胆寒。","临机一著妙，入境众心安。","闻已诛元恶，仍须问祸端。"]},{"t":"寄姚楚州 其二","f":"五言律诗","c":["庸将几误国，流民亦弄兵。","康时仗豪杰，了事是功名。","车马长淮路，貔貅细柳营。","山阳还旧观，并使虏尘清。"]},{"t":"寄赵茂实大著二首 其二","f":"五言律诗","c":["词臣工笔墨，亦足致功勋。","细草平戎策，兼为谕蜀文。","一言关治乱，千载有知闻。","应笑垂纶叟，愁吟对海云。"]},{"t":"寄赵茂实大著二首 其一","f":"五言律诗","c":["久坐图书府，方登著作庭。","人知才可敬，公以德为馨。","议论参诸老，文章本六经。","省中相别后，夜夜望奎星。"]},{"t":"寄赵漳州话病","f":"五言律诗","c":["听雨无聊赖，高眠独掩扉。","塞鸿书不到，海燕约同归。","吾道关通塞，人情有是非。","荆州相别后，王粲更谁依。"]},{"t":"寄赵德行","f":"七言律诗","c":["平生幸甚识诸公，未免归为田舍翁。","诗稿敢求经御览，客身自笑坐天穷。","肯将钓手遮西日，独耸吟肩诉北风。","枉使西山有遗恨，不能置我玉堂中。"]},{"t":"寄项宜甫兼简韩右司","f":"七言律诗","c":["匆匆不暇去相违，草草吟成送别诗。","千里江山客行远，三秋风雨桂开迟。","安居但欲无公事，举枉终须有直时。","若见右司烦寄语，世间公道要扶持。"]},{"t":"寄栗斋巩仲至","f":"五言律诗","c":["几度观朝报，差除不到君。","山林自台阁，文字即功勋。","吟苦孟东野，潜深杨子云。","一官虽偃蹇，千载有知闻。"]},{"t":"寄梅屋赵季防县尉","f":"五言律诗","c":["畴昔交游密，暌违岁月多。","石屏今老矣，梅屋病如何。","世路生荆棘，家山足薜萝。","共寻深处隐，此计莫蹉跎。"]},{"t":"寄清流王令君","f":"五言律诗","c":["朴直存吾道，一心唯向公。","知非巧宦者，直有古人风。","行志非为矫，洁身能固穷。","如何有廉吏，不入荐书中。"]},{"t":"寄虚斋赵侍郎 其二","f":"五言律诗","c":["灾异天垂戒，安危事可知。","试将黄雨證，请问白云司。","对客论孤愤，伤时赋五噫。","醉中忘万虑，安得酒如池。"]},{"t":"寄虚斋赵侍郎 其一","f":"五言律诗","c":["老眼开还阖，愁怀醉不醒。","乾坤多变故，人物晓天星。","药石匡时切，蓍龟见事灵。","得公十数辈，亦足壮朝廷。"]},{"t":"寄湖州杨伯子监丞","f":"七言律诗","c":["宛如公干卧漳滨，枕上穷吟过一春。","遣病每怀诗眷属，访医因问药君臣。","钻龟小卜占灾数，览镜羸形类别人。","寄语霅川贤太守，新诗莫厌话愁频。"]},{"t":"寄韩仲止","f":"五言律诗","c":["何以涧泉号，取其清又清。","天游一丘壑，孩视几公卿。","杯举即时酒，诗留后世名。","黄花秋意足，东望忆渊明。"]},{"t":"寄镇江王子文总卿","f":"五言律诗","c":["一代文章手，官如水样清。","三军皆饱德，诸将共谈兵。","铁瓮横天立，金山压浪平。","北人向南望，□□月分明。"]},{"t":"常宁县访许介之途中即景","f":"五言律诗","c":["竹径入茅屋，松坡连菜畦。","深潴沤麻水，斜竖采桑梯。","区别邻家鸭，群分各线鸡。","行人来少憩，假道过东溪。"]},{"t":"得古梅两枝","f":"五言律诗","c":["老干百年久，从教花事迟。","似枯元不死，因病反成奇。","玉破稀疏蕊，苔封古怪枝。","谁能知我意，相对岁寒时。"]},{"t":"族侄孙子荣之子神童颜老不幸短命而死哭之不足三诗以悼之 其二","f":"五言律诗","c":["昨应童科日，群儿立下风。","丰姿倾众目，文采动诸公。","两耳能兼听，六经皆暗通。","相期到杨晏，有始柰无终。"]},{"t":"族侄孙子荣之子神童颜老不幸短命而死哭之不足三诗以悼之 其一","f":"五言律诗","c":["亘古英灵在，颜回有后身。","年才十三岁，才过万千人。","学到由天悟，文高见理真。","再生仍再夭，无路问鸿钧。"]},{"t":"晚春次韵","f":"五言律诗","c":["酒醒愁难醒，春归客未归。","鶑啼花雨歇，燕立柳风微。","世路多殊辙，人生贵识机。","低头饱一粟，仰首愧云飞。"]},{"t":"晚望怀长沙故人","f":"五言律诗","c":["却扇清风起，楼头坐晚凉。","青山连远水，绿树带斜阳。","客路伤离别，人情果在亡。","定应今夜梦，随月到潇湘。"]},{"t":"望花山张老家","f":"五言律诗","c":["元从边上住，来此避兵兴。","麦麨朝充食，松明夜当灯。","蔽门麻菶菶，护壁石层层。","老妪逢人哭，吾儿在谢陵。"]},{"t":"梅","f":"七言律诗","c":["孤标粲粲压群葩，独占春风管岁华。","几树参差江上路，数枝装点野人家。","冰池照影何须月，雪岸闻香不见花。","绝似林间隐君子，自从幽处作生涯。"]},{"t":"梅花","f":"五言古诗","c":["细把南枝看，百花无此奇。","夜深钟月魄，□□□□□。","古树龙其似，寒香蝶不知。","幽兰开亦早，二妙喜同时。"]},{"t":"梅花","f":"七言律诗","c":["潇洒春葩缟寿阳，百花惟有此花强。","月中分外精神出，雪里几多风味长。","折向书窗疑是玉，吟来齿颊亦生香。","年年茅舍江村畔，勾引诗人费品量。"]},{"t":"梦与赵用父王子文陈叔方相会甚款","f":"五言律诗","c":["鼎足当州县，别来音问稀。","故人俱显达，吾道亦光辉。","三凤梦中见，孤鸿天外飞。","应怜江海客，白首未成归。"]},{"t":"梦中题林逢吉轩壁觉来全篇可读天明忘了落句","f":"五言律诗","c":["嚣尘不到眼，潇洒似僧家。","风月三千首，图书四十车。","绿垂当户柳，红映隔墙花。","好读天台赋，登楼咏落霞。"]},{"t":"淮上回九江","f":"五言律诗","c":["江水接淮水，扁舟去复回。","客程官路柳，心事故园梅。","活计鱼千里，空言水一杯。","石屏有茅屋，朝夕望归来。"]},{"t":"淮上春日","f":"五言律诗","c":["边寒客衣薄，渐喜暖风回。","社后未闻燕，春深方见梅。","壮怀频抚剑，孤愤强衔杯。","北望山河语，天时不再来。"]},{"t":"淮上寄赵茂实","f":"五言律诗","c":["渺渺长淮路，秋风落木悲。","乾坤限南北，胡虏迭兴衰。","志士言机会，中原入梦思。","江湖好山色，都在夕阳时。"]},{"t":"淮东赵漕领客东园赵世卿剩谈近日诸公仆谓今日东园之会想像欧苏风流不可见","f":"五言律诗","c":["今日东园会，能为野客期。","乾坤一南北，花木几兴衰。","亭馆经行地，欧苏无恙时。","风流不可见，烟雨谩题诗。"]},{"t":"淮岸阻风","f":"五言律诗","c":["舣棹枫林外，平沙步晚晴。","秋深红鹤至，波动白鸥惊。","荻浦留三日，江州计几程。","夜来风色好，行不待天明。"]},{"t":"清明前梦得花字","f":"七言律诗","c":["白头那办老生涯，幸有痴儿可主家。","百岁光阴一场梦，三春消息几番花。","扫松预造清明酒，入峡先租谷雨茶。","随分支吾度时节，那求不死炼丹砂。"]},{"t":"清明感伤","f":"五言律诗","c":["一笠戴春雨，愁来不可遮。","清明思上冢，昨夜梦还家。","归兴随流水，伤心对落花。","晋原松下泪，沾洒楚天涯。"]},{"t":"琅琊山中废寺","f":"五言律诗","c":["欲访山中寺，沿堤石甃长。","宝坊兵后废，御帖窖中藏。","故址生秋草，寒窗带夕阳。","孤僧出迎客，满口话凄凉。"]},{"t":"舂陵山中","f":"五言律诗","c":["地僻民风古，雨晴天气新。","空山竖奇石，乔木堕枯薪。","深入千崖路，多逢百岁人。","繁华凋性命，寂寞可全真。"]},{"t":"舂陵山中作写寄孔海翁","f":"五言律诗","c":["昨日分携后，回头望竹关。","相亲唯白水，所见但青山。","云近人家远，苔生石径斑。","闻钟知有寺，又在渺茫间。"]},{"t":"舂陵道上","f":"五言律诗","c":["云际寻行路，时逢一两家。","山川闲世界，耕钓小生涯。","病竹长新笋，寒芒摇落花。","溪翁解延客，连煮数杯茶。"]},{"t":"菊坡崔参政说平叛卒不得已拜经略之命岂敢言功","f":"七言律诗","c":["角巾私第自逍遥，诸老之中此老高。","无可柰何怀印绶，甚非得已用弓刀。","风生玉帐千兵肃，天落金牌一札褒。","缓急经心护乡井，生憎儿辈说功劳。"]},{"t":"萍乡县圃","f":"五言律诗","c":["亭榭八九所，一筇随往还。","四桥朱槛外，三径绿阴间。","凿浅通流水，凭高见远山。","琴堂判风月，一笑得双鬟。"]},{"t":"萍乡客舍","f":"五言律诗","c":["草罢惜春赋，持杯亦鲜欢。","檐楹双燕语，风雨百花残。","小阁无聊坐，征衣不耐寒。","地炉烧石炭，强把故书看。"]},{"t":"萧飞卿将使赴湖北戎幕诗送其行兼简秋壑贾总侍二首 其二","f":"五言律诗","c":["鄂渚三千里，遥遥望使星。","江湖今寂寞，桃李半凋零。","世有一秋壑，时无两石屏。","平生不相遇，老眼向谁青。"]},{"t":"萧飞卿将使赴湖北戎幕诗送其行兼简秋壑贾总侍二首 其一","f":"五言律诗","c":["文章萧颖士，一剑去从军。","远望西关路，愁看两浦云。","九霄腾意气，万里取功勋。","马上一杯酒，须斟满十分。"]},{"t":"萧仲有遗经堂","f":"五言律诗","c":["一经传世宝，说与子孙知。","欲作久长计，毋忘礼义为。","黄金生悔吝，白璧有瑕疵。","兼取庞公语，图安不遗危。"]},{"t":"萧学易何季皋和作别诗佳甚再用前韵","f":"七言律诗","c":["少年行脚白头归，不负平生汗漫期。","望断海山云漠漠，愁生江路草离离。","一篇王粲登楼赋，几首巴陵送别诗。","独倚篷窗无意绪，瓦盆倾酒忆金卮。"]},{"t":"鄂州戎治静憩亭","f":"五言律诗","c":["幽亭何处寻，岩树碧森森。","独坐生云石，少安经世心。","伴人双鹤立，多事一蝉吟。","提剑翻然起，中原秋草深。"]},{"t":"鄂渚烟波亭","f":"七言律诗","c":["倚遍南楼更鹤楼，小亭潇洒最宜秋。","接天烟浪来三峡，隔岸楼台又一州。","豪杰不生机事息，古今无尽大江流。","凭栏日暮怀乡国，崔颢诗中旧日愁。"]},{"t":"隆兴度夏借东湖驿安下","f":"五言律诗","c":["面对一池荷，四旁杨柳坡。","树阴遮日少，屋敞受风多。","疑是清凉国，暂为安乐窝。","人人争避暑，老子自婆娑。"]},{"t":"随军转运司王宣子上巳日会客","f":"七言律诗","c":["边头相遇若相期，又见随军转运司。","忆昨醉君京口酒，伤今读我石壕诗。","兰亭饮客酬佳节，淝水收功定几时。","准拟看花花较少，春风全在绿杨枝。"]},{"t":"雪后暖","f":"五言律诗","c":["先腊梅花谢，不冰溪水流。","早尝春菜饼，暖卸木终裘。","去岁三冬雪，今年百谷秋。","此冬无此瑞，又为老农忧。"]},{"t":"麻城道中","f":"五言律诗","c":["三杯成小醉，行处总堪诗。","临水知鱼乐，观山爱马迟。","林塘飞翡翠，篱落带酴醾。","问讯边头事，溪翁总不知。"]},{"t":"黄州竹楼呈谢国正","f":"七言律诗","c":["每日黄堂事了时，一心惟恐上楼迟。","发挥天地读周易，管领江山歌杜诗。","切戒吏来呈簿历，常邀客至共琴棋。","风流太守谁其似，半似元之半牧之。"]},{"t":"黄州偶成","f":"七言律诗","c":["雁叫淮南欲雪天，倚楼无味抱愁眠。","算从沧海白云际，行到黄州赤壁边。","万事忌于怀壮志，一生穷为耸吟肩。","鬓间白者休教镊，要使天知老可怜。"]},{"t":"黄道士出爻","f":"五言律诗","c":["林屋何潇洒，权为羽士家。","客来多载酒，僧至自煎茶。","试墨题新竹，携筇数落花。","饮中忙过日，无暇问丹砂。"]},{"t":"喜闻平峒寇","f":"五言律诗","c":["峒寇都平了，官军奏凯歌。","千山通道路，一雨洗干戈。","天地和风转，江湖春水多。","蜀中无近报，西贼定如何。"]},{"t":"喜梅雨既晴","f":"七言律诗","c":["屋角鸣禽弄好音，楼头夏木绿阴阴。","镊空白发愁根在，熟尽黄梅雨意深。","苔榻有泥妨客坐，稻田足水慰农心。","老夫已作丰年想，鼓腹思为击壤吟。"]},{"t":"彭绣使平叛卒后除经略小诗陈利害 其一","f":"五言律诗","c":["广东经略使，今古几人贤。","陛下用一士，民间有二天。","清风排瘴雨，廉德照贪泉。","龙节生光彩，鸾车奏凯旋。"]},{"t":"彭绣使平叛卒后除经略小诗陈利害 其三","f":"五言律诗","c":["乳虎恋巢穴，穷猿失木悲。","早须思一著，先要释群疑。","豪杰通心腹，人民无怨咨。","御军明纪律，威爱贵兼施。"]},{"t":"彭绣使平叛卒后除经略小诗陈利害 其二","f":"五言律诗","c":["斩蛟移鳄后，近水有惊鳞。","阃外尚多事，幕中无一人。","佩韦防狷急，强饭养精神。","罗致贤能士，仍须藻鉴真。"]},{"t":"提刑彭仲节平叛卒","f":"七言律诗","c":["千兵喝赏黄金尽，六月临戎白刃寒。","慷慨丈夫为事别，太平人物济时难。","谁言江左无王谢，今喜军中有范韩。","汉节梅花留不住，借君一剑斩楼兰。"]},{"t":"曾云巢同相勉李玉涧不赴召","f":"七言律诗","c":["诏书催赴紫宸班，九奏君王乞挂冠。","日暮倒行非我事，急流勇退有何难。","地灵不隐金砂胜，秋水长流玉涧寒。","好把山林寄图画，试教天下故人看。"]},{"t":"曾云巢年八十聪明不衰小楷写六经家有小楼日登览不倦诸监司尝荐遗逸","f":"五言律诗","c":["八十云巢老，诸公旧典刑。","心情古井水，辈行晓天星。","身健登高阁，眼明书六经。","尝闻荐遗逸，何以报朝廷。"]},{"t":"曾景建得罪道州听读","f":"七言律诗","c":["闻说乌台欲勘诗，此身幸不堕危机。","少陵酒后轻严武，太白花前忤贵妃。","迁客芬芳穷也达，故人评论是耶非。","饱参一勺濂溪水，带取光风霁月归。"]},{"t":"渝江绿阴亭九日燕集 其一","f":"五言律诗","c":["佳节重有感，人间行道难。","登高苦无地，把酒一凭栏。","山迥暮烟合，江空秋水寒。","沙头有鸂鶒，莫作鸳鸯看。"]},{"t":"渝江绿阴亭九日燕集 其二","f":"五言律诗","c":["九日江亭上，谁怜老孟嘉。","要人看白发，不用整乌纱。","寄兴题桐叶，长歌醉菊花。","归心徒自苦，犹在楚天涯。"]},{"t":"游云溪与郡宴用太守韵即事二首 其二","f":"七言律诗","c":["官府太平无一事，凝香座上著衰翁。","飘摇短棹游方沼，缥缈高楼倚半空。","把酒夜深霜落后，吹箫人在月明中。","使君笑指梅花说，去岁今年事不同。"]},{"t":"游云溪与郡宴用太守韵即事二首 其一","f":"七言律诗","c":["溪堂久矣无人到，千骑传呼五马来。","流水奔腾砥柱立，好山呈露晚云开。","指挥壮士驰骁骑，管领衰翁吊古梅。","笑问风流羊叔子，几人登览不尘埃。"]},{"t":"游天竺","f":"五言律诗","c":["好山看不了，遂借上方眠。","酒渴倾花露，诗清泻涧泉。","生无适俗韵，老欲结僧缘。","睡觉钟声晓，窗腾柏子烟。"]}]};